/// Submits answers for the oldest visible ask-tool request and resumes the blocked tool call.
/// 提交当前可见 ask 工具请求的答案，并恢复被阻塞的工具调用。
fn service_reply_pending_question(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request_id: String,
    answers: Vec<Vec<String>>,
) -> Result<WorkbenchSnapshot, String> {
    let agent_runtime = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.agent_runtime.clone().ok_or_else(|| {
            String::from("service is still starting; question runtime is not ready")
        })?
    };
    let answered = agent_runtime
        .question_runtime
        .reply(&request_id, answers)
        .map_err(|error| format!("failed to submit ask answers: {error}"))?;
    if !answered {
        return Err(format!(
            "pending ask request `{request_id}` is no longer active"
        ));
    }
    store_and_emit_pending_question_workbench_snapshot(&app, &state)
}

/// Rejects the visible ask-tool request after explicit user confirmation.
/// 在用户明确确认后拒绝当前可见 ask 工具请求。
fn service_reject_pending_question(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let agent_runtime = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.agent_runtime.clone().ok_or_else(|| {
            String::from("service is still starting; question runtime is not ready")
        })?
    };
    let rejected = agent_runtime
        .question_runtime
        .reject(&request_id)
        .map_err(|error| format!("failed to reject ask request: {error}"))?;
    if !rejected {
        return Err(format!(
            "pending ask request `{request_id}` is no longer active"
        ));
    }
    store_and_emit_pending_question_workbench_snapshot(&app, &state)
}

/// Loads one backend-validated draft for a user prompt edit dialog.
/// 加载一份供用户提示词编辑弹窗使用的后端校验草稿。
async fn service_get_user_prompt_edit_draft(
    state: SharedServiceBridgeState,
    conversation_id: String,
    message_id: String,
) -> Result<UserPromptEditDraftSummary, String> {
    let session_id = parse_session_id(&conversation_id)
        .ok_or_else(|| String::from("ERR_USER_PROMPT_EDIT_INVALID_CONVERSATION"))?;
    let controller_runtime = {
        let mut guard = state
            .lock()
            .map_err(|_| String::from("ERR_SERVICE_STATE_LOCK_FAILED"))?;
        if !webui_session_allows_user_prompt_editing(&mut guard, session_id) {
            return Err(String::from("ERR_USER_PROMPT_EDIT_SESSION_BUSY"));
        }
        guard
            .controller_runtime
            .clone()
            .ok_or_else(|| String::from("ERR_CONTROLLER_RUNTIME_NOT_READY"))?
    };
    let target =
        load_persisted_user_prompt_edit_draft(&controller_runtime, session_id, &message_id).await?;
    Ok(UserPromptEditDraftSummary {
        conversation_id,
        message_id,
        prompt: target.prompt,
        attachments: target
            .attachments
            .iter()
            .map(composer_attachment_summary_from_core)
            .collect(),
        running: false,
    })
}

/// Submits one user prompt edit by rolling back the tail and immediately replaying the edited prompt.
/// 通过回滚尾部并立即重放编辑后提示词来提交一次用户提示词编辑。
async fn service_submit_user_prompt_edit(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: UserPromptEditSubmitRequest,
) -> Result<WorkbenchSnapshot, String> {
    if request.stop_running {
        return Err(String::from("ERR_USER_PROMPT_EDIT_SESSION_BUSY"));
    }
    let session_id = parse_session_id(&request.conversation_id)
        .ok_or_else(|| String::from("ERR_USER_PROMPT_EDIT_INVALID_CONVERSATION"))?;
    let _validated_attachments = request
        .attachments
        .clone()
        .into_iter()
        .map(composer_attachment_summary_to_core)
        .collect::<Result<Vec<_>, _>>()?;
    let controller_runtime = {
        let mut guard = state
            .lock()
            .map_err(|_| String::from("ERR_SERVICE_STATE_LOCK_FAILED"))?;
        let controller_runtime = guard
            .controller_runtime
            .clone()
            .ok_or_else(|| String::from("ERR_CONTROLLER_RUNTIME_NOT_READY"))?;
        if !webui_session_allows_user_prompt_editing(&mut guard, session_id) {
            return Err(String::from("ERR_USER_PROMPT_EDIT_SESSION_BUSY"));
        }
        controller_runtime
    };
    let rollback = rollback_persisted_session_before_user_prompt(
        &controller_runtime,
        session_id,
        &request.message_id,
    )
    .await?;
    {
        let mut guard = state
            .lock()
            .map_err(|_| String::from("ERR_SERVICE_STATE_LOCK_FAILED"))?;
        let workspace = guard
            .workspace_snapshot
            .as_mut()
            .ok_or_else(|| String::from("ERR_WORKSPACE_SNAPSHOT_NOT_READY"))?;
        workspace
            .session_messages
            .insert(session_id, rollback.retained_messages.clone());
        workspace
            .session_runtime_state
            .insert(session_id, rollback.runtime_state);
        workspace.hydrated_session_ids.insert(session_id);
        workspace
            .session_run_phases
            .insert(session_id, SessionRunPhase::Ready);
        if let Some(session) = workspace
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        {
            session.status = SessionState::Completed;
            session.focus = String::new();
            session.last_updated_label = String::new();
            session.updated_at = current_unix_millis_text();
        }
        guard.workbench.messages = conversation_messages_from_session(
            &session_id.to_string(),
            rollback.retained_messages.as_slice(),
            false,
        );
        guard.workbench_generation = guard.workbench_generation.wrapping_add(1);
        guard.workbench = workbench_with_live_pending_question(&guard);
    }
    service_submit_conversation_prompt(
        app,
        state,
        None,
        Some(request.conversation_id),
        request.prompt,
        None,
        Some(String::from("build")),
        None,
        Some(request.attachments),
        None,
        None,
        None,
    )
    .await
}

/// Forks one persisted conversation into a new idle session and opens the clone.
/// 将一个持久化会话分叉为新的空闲会话并打开克隆。
async fn service_fork_conversation(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: ConversationForkRequest,
) -> Result<WorkbenchSnapshot, String> {
    let source_session_id = parse_session_id(&request.conversation_id)
        .ok_or_else(|| String::from("ERR_SESSION_FORK_INVALID_CONVERSATION"))?;
    let (controller_runtime, source_session, project_id) = {
        let mut guard = state
            .lock()
            .map_err(|_| String::from("ERR_SERVICE_STATE_LOCK_FAILED"))?;
        if !webui_session_allows_user_prompt_editing(&mut guard, source_session_id) {
            return Err(String::from("ERR_SESSION_FORK_SESSION_BUSY"));
        }
        let workspace = guard
            .workspace_snapshot
            .as_ref()
            .ok_or_else(|| String::from("ERR_WORKSPACE_SNAPSHOT_NOT_READY"))?;
        let source_session = workspace
            .sessions
            .iter()
            .find(|session| session.id == source_session_id)
            .cloned()
            .ok_or_else(|| String::from("ERR_SESSION_FORK_SOURCE_NOT_FOUND"))?;
        let project_id = owning_project_id_for_session(workspace, source_session_id)
            .ok_or_else(|| String::from("ERR_SESSION_FORK_PROJECT_NOT_FOUND"))?;
        let controller_runtime = guard
            .controller_runtime
            .clone()
            .ok_or_else(|| String::from("ERR_CONTROLLER_RUNTIME_NOT_READY"))?;
        (controller_runtime, source_session, project_id)
    };
    let target_session_id = SessionId::new_v4();
    let fork_title = if request.title.trim().is_empty() {
        source_session.title.clone()
    } else {
        request.title.trim().to_string()
    };
    let fork_result = fork_persisted_session(
        &controller_runtime,
        &source_session,
        &project_id,
        target_session_id,
        fork_title,
    )
    .await?;
    if let Some(before_message_id) = request
        .before_message_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        rollback_persisted_session_before_user_prompt(
            &controller_runtime,
            fork_result.session.id,
            before_message_id,
        )
        .await?;
    }
    record_persisted_session_fork_source_marker(
        &controller_runtime,
        fork_result.session.id,
        &source_session,
        &project_id,
    )?;
    let target_session_id_text = fork_result.session.id.to_string();
    load_hydrated_session_workbench(
        &app,
        &state,
        fork_result.session.id,
        &target_session_id_text,
    )
    .await
    .map(|hydrated| hydrated.workbench)
}

/// Rebuilds only the ask-modal projection on the retained workbench snapshot and emits it.
/// 仅重建保留工作台快照上的 ask 弹窗投影并发送事件。
fn store_and_emit_pending_question_workbench_snapshot(
    app: &ServiceEventEmitter,
    state: &SharedServiceBridgeState,
) -> Result<WorkbenchSnapshot, String> {
    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let pending_question =
            pending_question_snapshot_from_agent_runtime(guard.agent_runtime.as_ref());
        guard.workbench_generation = guard.workbench_generation.wrapping_add(1);
        guard.workbench.pending_question = pending_question;
        guard.workbench.clone()
    };
    emit_service_event_with_trace(
        app,
        "pending_question_workbench_emit",
        ServiceEvent::Workbench(Box::new(workbench.clone())),
    );
    Ok(workbench)
}

/// Installs the WebUI projection callback used by the ask-question runtime.
/// 安装 ask 提问运行时使用的 WebUI 投影回调。
fn install_webui_question_runtime_event_bridge(
    app: &ServiceEventEmitter,
    state: &SharedServiceBridgeState,
    question_runtime: &Arc<QuestionRuntime>,
) -> Result<(), String> {
    let app = app.clone();
    let state = Arc::clone(state);
    let callback: PendingQuestionChangeCallback = Arc::new(move || {
        if let Err(error) = store_and_emit_pending_question_workbench_snapshot(&app, &state) {
            webui_trace(
                "pending_question_projection_failed",
                format!("error={error}"),
            );
        }
    });
    question_runtime.set_change_callback(Some(callback))
}

/// Returns the retained workbench with the latest live ask-runtime pending request attached.
/// 返回附加最新实时 ask 运行时待处理请求的保留工作台。
fn workbench_with_live_pending_question(guard: &ServiceBridgeState) -> WorkbenchSnapshot {
    let mut workbench = guard.workbench.clone();
    if let Some(workspace_snapshot) = guard.workspace_snapshot.as_ref() {
        workbench.hydrated_conversation_windows =
            hydrated_conversation_window_summaries(&guard.hydrated_conversation_windows);
        append_hydrated_workspace_messages(&mut workbench.messages, workspace_snapshot);
    }
    workbench.pending_question =
        pending_question_snapshot_from_agent_runtime(guard.agent_runtime.as_ref());
    workbench
}

/// Loads the recent transcript window for one conversation.
/// 加载单个会话的最近转录窗口。
async fn service_session_messages(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    session_id: String,
) -> Result<ConversationMessagesLoadResponse, String> {
    let parsed_session_id = session_id
        .parse::<SessionId>()
        .map_err(|error| format!("invalid session id '{session_id}': {error}"))?;
    if let Some(response) =
        retained_hydrated_session_messages_response(&app, &state, parsed_session_id, &session_id)?
    {
        return Ok(response);
    }
    emit_conversation_hydration_progress(
        &app,
        &state,
        conversation_hydration_progress(
            &session_id,
            ConversationHydrationStatus::Loading,
            "locating",
            5,
            "正在定位会话。",
        ),
    )?;
    let hydrated = load_hydrated_session_workbench(&app, &state, parsed_session_id, &session_id)
        .await
        .map_err(|error| {
            let _ = emit_conversation_hydration_progress(
                &app,
                &state,
                conversation_hydration_progress(
                    &session_id,
                    ConversationHydrationStatus::Error,
                    "failed",
                    100,
                    &error,
                ),
            );
            error
        })?;
    let progress = conversation_hydration_progress(
        &session_id,
        ConversationHydrationStatus::Ready,
        "done",
        100,
        "会话载入完成。",
    );
    let mut completed_workbench = hydrated.workbench;
    completed_workbench.conversation_hydration = Some(progress.clone());
    let messages = completed_workbench.messages.clone();
    {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.workbench_generation = guard.workbench_generation.wrapping_add(1);
        guard.workbench = completed_workbench.clone();
    }
    emit_workbench_event(&app, &completed_workbench);
    Ok(ConversationMessagesLoadResponse {
        workbench: Box::new(completed_workbench),
        messages,
        earliest_ordinal: hydrated.earliest_ordinal,
        has_more_history: hydrated.has_more_history,
        progress,
    })
}

/// Returns a retained hydrated conversation window without re-reading persisted session files.
/// 返回已保留的水合会话窗口，避免重新读取持久化会话文件。
fn retained_hydrated_session_messages_response(
    app: &ServiceEventEmitter,
    state: &SharedServiceBridgeState,
    parsed_session_id: SessionId,
    session_id: &str,
) -> Result<Option<ConversationMessagesLoadResponse>, String> {
    let mut guard = state
        .lock()
        .map_err(|error| format!("failed to lock service state: {error}"))?;
    let (window, session_messages, allow_user_prompt_editing) = {
        let Some(workspace_snapshot) = guard.workspace_snapshot.as_ref() else {
            return Ok(None);
        };
        if !workspace_snapshot
            .hydrated_session_ids
            .contains(&parsed_session_id)
        {
            return Ok(None);
        }
        let Some(window) = guard
            .hydrated_conversation_windows
            .get(&parsed_session_id)
            .copied()
        else {
            return Ok(None);
        };
        let Some(session_messages) = workspace_snapshot
            .session_messages
            .get(&parsed_session_id)
            .cloned()
        else {
            return Ok(None);
        };
        let allow_user_prompt_editing = workspace_surface_allows_user_prompt_editing(
            workspace_snapshot,
            parsed_session_id,
            None,
        );
        (window, session_messages, allow_user_prompt_editing)
    };
    if let Some(workspace_snapshot) = guard.workspace_snapshot.as_mut() {
        workspace_snapshot.selected_session = parsed_session_id;
    }
    guard.active_subagent_panel = None;
    let mut messages = conversation_messages_from_session(
        session_id,
        &session_messages,
        allow_user_prompt_editing,
    );
    if let Some(workspace_snapshot) = guard.workspace_snapshot.as_ref() {
        append_hydrated_workspace_messages(&mut messages, workspace_snapshot);
    }
    let progress = conversation_hydration_progress(
        session_id,
        ConversationHydrationStatus::Ready,
        "done",
        100,
        "会话载入完成。",
    );
    guard.workbench.selected_conversation_id = Some(session_id.to_string());
    guard.workbench.messages = messages.clone();
    guard.workbench.hydrated_conversation_windows =
        hydrated_conversation_window_summaries(&guard.hydrated_conversation_windows);
    guard.workbench.conversation_hydration = Some(progress.clone());
    guard.workbench.subagent_navigation = None;
    guard.workbench_generation = guard.workbench_generation.wrapping_add(1);
    let workbench = guard.workbench.clone();
    drop(guard);
    emit_workbench_event(app, &workbench);
    Ok(Some(ConversationMessagesLoadResponse {
        workbench: Box::new(workbench),
        messages,
        earliest_ordinal: window.earliest_ordinal,
        has_more_history: window.has_more_history,
        progress,
    }))
}

/// Loads one older transcript page and merges it into the retained conversation window.
/// 加载一页更早转录历史，并将其合并进保留的会话窗口。
async fn service_session_history_page(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    session_id: String,
    before_ordinal: i64,
) -> Result<ConversationHistoryPageResponse, String> {
    let parsed_session_id = session_id
        .parse::<SessionId>()
        .map_err(|error| format!("invalid session id '{session_id}': {error}"))?;
    let controller_runtime = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.controller_runtime.clone().ok_or_else(|| {
            String::from("service is still starting; controller runtime is not ready")
        })?
    };
    let page = vulcan_workspace_store::workspace_store::load_session_history_page(
        controller_runtime,
        parsed_session_id,
        before_ordinal,
        SELECTED_SESSION_TURN_LOAD_LIMIT,
    )
    .await?;
    let page_messages = conversation_messages_from_session(&session_id, &page.messages, false);
    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let Some(workspace_snapshot) = guard.workspace_snapshot.as_mut() else {
            return Err(String::from("service workspace snapshot is not ready"));
        };
        let merged_messages = merge_older_session_history_page(
            workspace_snapshot
                .session_messages
                .entry(parsed_session_id)
                .or_default(),
            &page,
        );
        let allow_user_prompt_editing = workspace_surface_allows_user_prompt_editing(
            workspace_snapshot,
            parsed_session_id,
            None,
        );
        remember_hydrated_conversation_window(
            &mut guard.hydrated_conversation_windows,
            parsed_session_id,
            page.earliest_ordinal,
            page.has_more_history,
        );
        guard.workbench.hydrated_conversation_windows =
            hydrated_conversation_window_summaries(&guard.hydrated_conversation_windows);
        if guard.workbench.selected_conversation_id.as_deref() == Some(session_id.as_str()) {
            guard.workbench.messages = conversation_messages_from_session(
                &session_id,
                &merged_messages,
                allow_user_prompt_editing,
            );
        }
        guard.workbench_generation = guard.workbench_generation.wrapping_add(1);
        guard.workbench.clone()
    };
    emit_workbench_event(&app, &workbench);
    Ok(ConversationHistoryPageResponse {
        session_id,
        workbench: Box::new(workbench),
        messages: page_messages,
        earliest_ordinal: page.earliest_ordinal,
        has_more_history: page.has_more_history,
    })
}

/// Prepends an older history page into the retained session message window without duplicating rows.
/// 将更早历史页前置合并到保留的会话消息窗口中，并避免重复行。
fn merge_older_session_history_page(
    retained_messages: &mut Vec<SessionMessageEntry>,
    page: &SessionHistoryPage,
) -> Vec<SessionMessageEntry> {
    let mut seen_keys = retained_messages
        .iter()
        .map(session_message_entry_stable_merge_key)
        .collect::<BTreeSet<_>>();
    let mut merged = page
        .messages
        .iter()
        .filter(|message| seen_keys.insert(session_message_entry_stable_merge_key(message)))
        .cloned()
        .collect::<Vec<_>>();
    merged.append(retained_messages);
    *retained_messages = merged.clone();
    retained_messages.clone()
}

/// Returns the stable merge key used by transcript history pagination.
/// 返回转录历史分页使用的稳定合并键。
fn session_message_entry_stable_merge_key(message: &SessionMessageEntry) -> String {
    if !message.id.is_empty() {
        return message.id.clone();
    }
    format!(
        "{}:{}:{}",
        message.created_at,
        message.record_kind.as_persisted_key(),
        message.body
    )
}

/// Loads one conversation using the original selected-session workbench projection path.
/// 使用原始选中会话工作台投影路径加载单个会话。
async fn load_hydrated_session_workbench(
    app: &ServiceEventEmitter,
    state: &SharedServiceBridgeState,
    parsed_session_id: SessionId,
    session_id: &str,
) -> Result<HydratedSessionWorkbench, String> {
    let (
        controller_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
        preserved_workspace_run_state,
        provider_configuration,
        ai_tool_configuration,
        live_context_budgets,
        agent_runtime_for_status,
        live_listener_task_ids,
    ) = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let controller_runtime = guard.controller_runtime.clone().ok_or_else(|| {
            String::from("service is still starting; controller runtime is not ready")
        })?;
        let active_kernel_sessions = active_kernel_session_ids(&guard);
        let preserved_workspace_run_state = capture_preserved_workspace_run_state(
            guard.workspace_snapshot.as_ref(),
            &active_kernel_sessions,
            None,
        );
        let provider_configuration = guard
            .agent_runtime
            .as_ref()
            .map(|runtime| runtime.provider_configuration.clone())
            .unwrap_or_default();
        let ai_tool_configuration = guard
            .agent_runtime
            .as_ref()
            .map(|runtime| runtime.ai_tool_configuration.clone())
            .unwrap_or_default();
        (
            controller_runtime,
            cached_luaskills_catalog_from_state(&guard),
            guard.token_budget_runtime.clone().ok_or_else(|| {
                String::from("service is still starting; token budget runtime is not ready")
            })?,
            cached_mcp_catalog_from_state(&guard),
            guard.startup.recent_logs.clone(),
            preserved_workspace_run_state,
            provider_configuration,
            ai_tool_configuration,
            guard.live_context_budgets.clone(),
            guard.agent_runtime.clone(),
            guard.detached_subagent_task_listeners.clone(),
        )
    };
    emit_conversation_hydration_progress(
        app,
        state,
        conversation_hydration_progress(
            session_id,
            ConversationHydrationStatus::Loading,
            "readingIndex",
            20,
            "正在读取消息索引。",
        ),
    )?;
    let mut refreshed_snapshot =
        vulcan_workspace_store::workspace_store::load_workspace_index_snapshot(
            controller_runtime.clone(),
        )
        .await?;
    preserve_active_session_run_state(
        preserved_workspace_run_state.as_ref(),
        &mut refreshed_snapshot,
    );
    refreshed_snapshot.selected_session = parsed_session_id;
    let project_id = owning_project_id_for_session(&refreshed_snapshot, parsed_session_id);
    emit_conversation_hydration_progress(
        app,
        state,
        conversation_hydration_progress(
            session_id,
            ConversationHydrationStatus::Loading,
            "readingMessages",
            55,
            "正在读取消息内容。",
        ),
    )?;
    let hydration = match project_id.as_deref() {
        Some(project_id) => {
            vulcan_workspace_store::workspace_store::load_session_display_hydration_snapshot_for_project(
                controller_runtime.clone(),
                project_id,
                parsed_session_id,
                SELECTED_SESSION_TURN_LOAD_LIMIT,
            )
            .await
        }
        None => {
            vulcan_workspace_store::workspace_store::load_session_display_hydration_snapshot(
                controller_runtime.clone(),
                parsed_session_id,
                SELECTED_SESSION_TURN_LOAD_LIMIT,
            )
            .await
        }
    }
    .or_else(|error| {
        if is_missing_segmented_session_file_error(&error) {
            Ok(empty_session_hydration_snapshot(parsed_session_id))
        } else {
            Err(error)
        }
    })?;
    let earliest_ordinal = hydration.earliest_ordinal;
    let has_more_history = hydration.has_more_history;
    emit_conversation_hydration_progress(
        app,
        state,
        conversation_hydration_progress(
            session_id,
            ConversationHydrationStatus::Loading,
            "projecting",
            85,
            "正在整理显示数据。",
        ),
    )?;
    apply_hydration_to_selected_workspace_snapshot(
        &controller_runtime,
        &mut refreshed_snapshot,
        parsed_session_id,
        hydration,
        agent_runtime_for_status
            .as_ref()
            .map(|runtime| &runtime.task_runtime),
        &live_listener_task_ids,
    )?;
    sync_selected_session_goal_summary_from_store(
        state,
        controller_runtime.clone(),
        parsed_session_id,
    )
    .await?;
    let (surface_messages, subagent_navigation, session_goal_summaries, hydrated_windows) = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let active_kernel_sessions = active_kernel_session_ids(&guard);
        let preserved_workspace_run_state = capture_preserved_workspace_run_state(
            guard.workspace_snapshot.as_ref(),
            &active_kernel_sessions,
            None,
        );
        preserve_active_session_run_state(
            preserved_workspace_run_state.as_ref(),
            &mut refreshed_snapshot,
        );
        let mut hydrated_windows = guard.hydrated_conversation_windows.clone();
        remember_hydrated_conversation_window(
            &mut hydrated_windows,
            parsed_session_id,
            earliest_ordinal,
            has_more_history,
        );
        retain_hydrated_conversation_windows_for_workspace(
            &mut hydrated_windows,
            &refreshed_snapshot,
        );
        (
            active_surface_messages_from_workspace_and_state(&mut guard, &refreshed_snapshot),
            subagent_navigation_snapshot_from_state(&mut guard, &refreshed_snapshot),
            guard.session_goal_summaries.clone(),
            hydrated_windows,
        )
    };
    let hydrated_window_summaries = hydrated_conversation_window_summaries(&hydrated_windows);
    let workbench = workbench_from_runtime(
        &controller_runtime,
        agent_runtime_for_status
            .as_ref()
            .map(|agent_runtime| agent_runtime.command_session_runtime.as_ref()),
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &provider_configuration,
        &ai_tool_configuration,
        &refreshed_snapshot,
        surface_messages.as_slice(),
        subagent_navigation,
        pending_question_snapshot_from_agent_runtime(agent_runtime_for_status.as_ref()),
        &logs,
        &live_context_budgets,
        &session_goal_summaries,
        &hydrated_window_summaries,
    );
    {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.hydrated_conversation_windows = hydrated_windows;
        guard.workspace_snapshot = Some(refreshed_snapshot);
    }
    Ok(HydratedSessionWorkbench {
        workbench,
        earliest_ordinal,
        has_more_history,
    })
}

/// Builds an empty hydration payload for a missing segmented session file.
/// 为缺失分段会话文件构建空水合载荷。
fn empty_session_hydration_snapshot(session_id: SessionId) -> SessionHydrationSnapshot {
    SessionHydrationSnapshot {
        session_id,
        messages: Vec::new(),
        tool_detail_messages: Vec::new(),
        compactions: Vec::new(),
        runtime_state: None,
        earliest_ordinal: None,
        has_more_history: false,
    }
}

/// Applies a hydrated selected session to a workspace snapshot before WebUI projection.
/// 在 WebUI 投影之前将已水合的选中会话应用到工作区快照。
fn apply_hydration_to_selected_workspace_snapshot(
    controller_runtime: &ControllerRuntimeHandle,
    workspace_snapshot: &mut WorkspaceSnapshot,
    session_id: SessionId,
    hydration: SessionHydrationSnapshot,
    task_runtime: Option<&Arc<TaskRuntime>>,
    live_listener_task_ids: &BTreeSet<SessionId>,
) -> Result<(), String> {
    workspace_snapshot
        .session_messages
        .insert(session_id, hydration.messages);
    workspace_snapshot
        .session_compactions
        .insert(session_id, hydration.compactions);
    if let Some(runtime_state) = hydration.runtime_state {
        workspace_snapshot
            .session_runtime_state
            .insert(session_id, runtime_state);
    }
    workspace_snapshot.hydrated_session_ids.insert(session_id);
    apply_persisted_task_mirror_statuses_to_workspace(
        controller_runtime,
        workspace_snapshot,
        session_id,
        |task_id| {
            webui_subagent_task_has_live_run(
                task_runtime,
                live_listener_task_ids.contains(&task_id),
                task_id,
            )
        },
    )?;
    Ok(())
}

/// Builds one lazy conversation hydration progress payload.
/// 构建单个懒加载会话正文水合进度载荷。
fn conversation_hydration_progress(
    session_id: &str,
    status: ConversationHydrationStatus,
    phase: &str,
    percent: u8,
    message: &str,
) -> ConversationHydrationProgress {
    ConversationHydrationProgress {
        session_id: session_id.to_string(),
        status,
        phase: phase.to_string(),
        message: message.to_string(),
        percent: percent.min(100),
    }
}

/// Stores and emits one lazy conversation hydration progress update.
/// 存储并发送一条懒加载会话正文水合进度更新。
fn emit_conversation_hydration_progress(
    app: &ServiceEventEmitter,
    state: &SharedServiceBridgeState,
    progress: ConversationHydrationProgress,
) -> Result<(), String> {
    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.workbench.conversation_hydration = Some(progress);
        guard.workbench.clone()
    };
    emit_workbench_event(app, &workbench);
    Ok(())
}

/// Loads one hidden tool-detail payload by stable record id or tool-call id fallback.
/// 按稳定记录标识加载隐藏工具详情载荷，并支持工具调用标识回退。
async fn service_session_tool_detail(
    state: SharedServiceBridgeState,
    session_id: String,
    record_id: Option<String>,
    tool_call_id: Option<String>,
    seq: Option<u64>,
    message_index: Option<usize>,
) -> Result<Value, String> {
    let parsed_session_id = session_id
        .parse::<SessionId>()
        .map_err(|error| format!("invalid session id '{session_id}': {error}"))?;
    let controller_runtime = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        if let Some(payload) = guard
            .workspace_snapshot
            .as_ref()
            .and_then(|workspace| workspace.session_runtime_state.get(&parsed_session_id))
            .and_then(|runtime_state| {
                find_tool_detail_record(
                    runtime_state.conversation_state.records.iter(),
                    record_id.as_deref(),
                    tool_call_id.as_deref(),
                    message_index,
                )
                .map(|record| tool_detail_payload_from_session_record(record, seq, message_index))
            })
        {
            return Ok(payload);
        }
        guard.controller_runtime.clone().ok_or_else(|| {
            String::from("service is still starting; controller runtime is not ready")
        })?
    };
    let transcript_page = vulcan_workspace_store::workspace_store::load_session_transcript_window(
        controller_runtime,
        parsed_session_id,
        SELECTED_SESSION_TURN_LOAD_LIMIT,
    )
    .await?;
    let transcript_messages = transcript_page
        .messages
        .iter()
        .chain(transcript_page.tool_detail_messages.iter())
        .collect::<Vec<_>>();
    find_tool_detail_message(
        transcript_messages.iter().copied(),
        record_id.as_deref(),
        tool_call_id.as_deref(),
        message_index,
    )
    .map(|message| tool_detail_payload_from_session_message(message, seq, message_index))
    .ok_or_else(|| {
        record_id
            .map(|record_id| format!("tool detail record not found: {record_id}"))
            .unwrap_or_else(|| {
                format!(
                    "tool detail record not found for tool call: {}",
                    tool_call_id.unwrap_or_else(|| String::from("<missing>"))
                )
            })
    })
}

/// Finds a hidden tool-detail message by precise record id first, then by tool-call id.
/// 先按精确记录标识查找隐藏工具详情，再按工具调用标识回退查找。
fn find_tool_detail_message<'a>(
    messages: impl IntoIterator<Item = &'a SessionMessageEntry>,
    record_id: Option<&str>,
    tool_call_id: Option<&str>,
    message_index: Option<usize>,
) -> Option<&'a SessionMessageEntry> {
    let messages = messages.into_iter().collect::<Vec<_>>();
    if let Some(record_id) = record_id.filter(|value| !value.trim().is_empty()) {
        if let Some(message) = message_index
            .and_then(|index| messages.get(index).copied())
            .filter(|message| message.id == record_id)
        {
            return Some(message);
        }
        if let Some(message) = messages
            .iter()
            .copied()
            .find(|message| message.id == record_id)
        {
            return Some(message);
        }
    }
    let tool_call_id = tool_call_id?.trim();
    if tool_call_id.is_empty() {
        return None;
    }
    messages.iter().copied().find(|message| {
        matches!(
            message.record_kind,
            SessionMessageRecordKind::ToolDetailOutput | SessionMessageRecordKind::ToolResultOutput
        ) && session_message_tool_call_id(message) == Some(tool_call_id)
    })
}

/// Finds a hidden runtime conversation record by precise record id first, then by tool-call id.
/// 先按精确记录标识查找隐藏运行时会话记录，再按工具调用标识回退查找。
fn find_tool_detail_record<'a>(
    records: impl IntoIterator<Item = &'a SessionConversationRecord>,
    record_id: Option<&str>,
    tool_call_id: Option<&str>,
    message_index: Option<usize>,
) -> Option<&'a SessionConversationRecord> {
    let records = records.into_iter().collect::<Vec<_>>();
    if let Some(record_id) = record_id.filter(|value| !value.trim().is_empty()) {
        if let Some(record) = message_index
            .and_then(|index| records.get(index).copied())
            .filter(|record| record.id == record_id)
        {
            return Some(record);
        }
        if let Some(record) = records
            .iter()
            .copied()
            .find(|record| record.id == record_id)
        {
            return Some(record);
        }
    }
    let tool_call_id = tool_call_id?.trim();
    if tool_call_id.is_empty() {
        return None;
    }
    records.iter().copied().find(|record| {
        matches!(
            record.record_kind,
            SessionMessageRecordKind::ToolDetailOutput | SessionMessageRecordKind::ToolResultOutput
        ) && session_record_tool_call_id(record) == Some(tool_call_id)
    })
}

/// Builds the JSON payload returned to the WebUI detail modal.
/// 构建返回给 WebUI 详情弹窗的 JSON 载荷。
fn tool_detail_payload_from_session_message(
    message: &SessionMessageEntry,
    seq: Option<u64>,
    message_index: Option<usize>,
) -> Value {
    json!({
        "body": message.body.clone(),
        "metadata": message.metadata.clone(),
        "seq": seq,
        "message_index": message_index,
    })
}

/// Builds the JSON payload returned from an in-memory runtime conversation record.
/// 从内存态运行时会话记录构建返回给 WebUI 的 JSON 载荷。
fn tool_detail_payload_from_session_record(
    record: &SessionConversationRecord,
    seq: Option<u64>,
    message_index: Option<usize>,
) -> Value {
    json!({
        "body": record.body.clone(),
        "metadata": record.metadata.clone(),
        "seq": seq,
        "message_index": message_index,
    })
}

/// Extracts the stable tool-call id from session message metadata.
/// 从会话消息元数据中提取稳定工具调用标识。
fn session_message_tool_call_id(message: &SessionMessageEntry) -> Option<&str> {
    message
        .metadata
        .as_ref()
        .and_then(|metadata| {
            metadata
                .get("tool_call_id")
                .or_else(|| metadata.get("toolCallId"))
        })
        .and_then(Value::as_str)
}

/// Extracts the stable tool-call id from runtime record metadata.
/// 从运行时记录元数据中提取稳定工具调用标识。
fn session_record_tool_call_id(record: &SessionConversationRecord) -> Option<&str> {
    record
        .metadata
        .as_ref()
        .and_then(|metadata| {
            metadata
                .get("tool_call_id")
                .or_else(|| metadata.get("toolCallId"))
        })
        .and_then(Value::as_str)
}

/// Rejects the retired native attachment picker RPC.
/// 拒绝已退役的原生附件选择器 RPC。
async fn service_pick_composer_attachments(
    _state: SharedServiceBridgeState,
    _project_id: Option<String>,
    _conversation_id: Option<String>,
    _kind: Option<String>,
) -> Result<Vec<ComposerAttachmentSummary>, String> {
    Err(String::from(
        "原生附件选择器已从服务壳层移除，请使用 WebUI 文件上传或路径暂存接口。",
    ))
}

/// Stages existing local paths as composer attachments.
/// 将已有本地路径暂存为输入区附件。
async fn service_stage_composer_attachment_paths(
    state: SharedServiceBridgeState,
    project_id: Option<String>,
    conversation_id: Option<String>,
    paths: Vec<String>,
) -> Result<Vec<ComposerAttachmentSummary>, String> {
    let workspace_path = composer_attachment_workspace_path(
        &state,
        project_id.as_deref(),
        conversation_id.as_deref(),
    )?;
    let paths = paths.into_iter().map(PathBuf::from).collect::<Vec<_>>();
    stage_composer_attachment_paths_for_workspace(&workspace_path, paths)
}

/// Stages one browser-provided in-memory file as a composer attachment.
/// 将浏览器提供的一份内存文件暂存为输入区附件。
async fn service_stage_composer_attachment_bytes(
    state: SharedServiceBridgeState,
    project_id: Option<String>,
    conversation_id: Option<String>,
    file_name: String,
    mime_type: String,
    data_base64: String,
) -> Result<ComposerAttachmentSummary, String> {
    let workspace_path = composer_attachment_workspace_path(
        &state,
        project_id.as_deref(),
        conversation_id.as_deref(),
    )?;
    let descriptor = attachment_descriptor_from_mime_type(&mime_type)
        .or_else(|| attachment_descriptor_from_path_fallback(&file_name))
        .ok_or_else(|| format!("文件 `{}` 不是受支持的附件格式。", file_name.trim()))?;
    let bytes = BASE64_STANDARD
        .decode(data_base64.trim())
        .map_err(|error| format!("解码附件 `{}` 失败：{}。", file_name.trim(), error))?;
    let attachment = stage_attachment_bytes(
        &workspace_path,
        &descriptor,
        file_name.trim(),
        None,
        bytes.as_slice(),
    )?;
    Ok(composer_attachment_summary_from_core(&attachment))
}

/// Resolves the project workspace path used to stage one composer attachment.
/// 解析暂存输入区附件时使用的项目工作区路径。
fn composer_attachment_workspace_path(
    state: &SharedServiceBridgeState,
    project_id: Option<&str>,
    conversation_id: Option<&str>,
) -> Result<String, String> {
    let guard = state
        .lock()
        .map_err(|error| format!("failed to lock service state: {error}"))?;
    let Some(workspace_snapshot) = guard.workspace_snapshot.as_ref() else {
        return Ok(normalized_workspace_path_text_from_path(&workspace_root()));
    };
    let owner_project_id = conversation_id
        .and_then(parse_session_id)
        .and_then(|session_id| {
            workspace_snapshot
                .sessions
                .iter()
                .find(|session| session.id == session_id)
                .and_then(|session| session.project_id.as_deref())
        })
        .or(project_id)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let Some(owner_project_id) = owner_project_id else {
        return Ok(normalized_workspace_path_text_from_path(&workspace_root()));
    };
    Ok(workspace_snapshot
        .task_projects
        .iter()
        .find(|project| project.id == owner_project_id)
        .map(|project| project.path.clone())
        .unwrap_or_else(|| normalized_workspace_path_text_from_path(&workspace_root())))
}

/// Stages local paths for a resolved workspace path and converts them to service DTOs.
/// 为已解析的工作区路径暂存本地路径，并转换为 service DTO。
fn stage_composer_attachment_paths_for_workspace(
    workspace_path: &str,
    paths: Vec<PathBuf>,
) -> Result<Vec<ComposerAttachmentSummary>, String> {
    paths
        .iter()
        .map(|path| stage_attachment_file(workspace_path, path))
        .map(|result| result.map(|attachment| composer_attachment_summary_from_core(&attachment)))
        .collect()
}

/// Converts a core conversation attachment into the WebUI service DTO.
/// 将核心会话附件转换为 WebUI service DTO。
fn composer_attachment_summary_from_core(
    attachment: &ConversationAttachment,
) -> ComposerAttachmentSummary {
    ComposerAttachmentSummary {
        kind: attachment.kind.modality_name().to_string(),
        file_name: attachment.file_name.clone(),
        local_path: attachment.local_path.clone(),
        source_path: attachment.source_path.clone(),
        asset_id: attachment.asset_id.clone(),
        byte_len: attachment.byte_len,
        preview_local_path: attachment.preview_local_path.clone(),
        mime_type: attachment.mime_type.clone(),
    }
}

/// Converts a WebUI service attachment DTO back into the core conversation attachment.
/// 将 WebUI service 附件 DTO 转回核心会话附件。
fn composer_attachment_summary_to_core(
    summary: ComposerAttachmentSummary,
) -> Result<ConversationAttachment, String> {
    Ok(ConversationAttachment {
        kind: parse_composer_attachment_kind(&summary.kind)?,
        file_name: summary.file_name,
        local_path: summary.local_path,
        source_path: summary.source_path,
        asset_id: summary.asset_id,
        byte_len: summary.byte_len,
        preview_local_path: summary.preview_local_path,
        mime_type: summary.mime_type,
    })
}

/// Parses one stable composer attachment kind key.
/// 解析单个稳定输入区附件类型键。
fn parse_composer_attachment_kind(value: &str) -> Result<ConversationAttachmentKind, String> {
    match value.trim().to_ascii_lowercase().as_str() {
        "image" => Ok(ConversationAttachmentKind::Image),
        "audio" => Ok(ConversationAttachmentKind::Audio),
        "video" => Ok(ConversationAttachmentKind::Video),
        "pdf" | "document" => Ok(ConversationAttachmentKind::Pdf),
        other => Err(format!("不支持的附件类型：{other}")),
    }
}

/// Resolves an attachment descriptor from a browser file name when the MIME type is missing.
/// 当浏览器未提供 MIME 类型时，从文件名解析附件描述。
fn attachment_descriptor_from_path_fallback(
    file_name: &str,
) -> Option<vulcan_agent_runtime::attachment_assets::AttachmentDescriptor> {
    attachment_descriptor_from_path(Path::new(file_name))
}

/// Returns the localized label used by the native file picker filter.
/// 返回原生文件选择器过滤器使用的本地化名称。
fn composer_attachment_kind_label(kind: &ConversationAttachmentKind) -> &'static str {
    match kind {
        ConversationAttachmentKind::Image => "图片",
        ConversationAttachmentKind::Audio => "音频",
        ConversationAttachmentKind::Video => "视频",
        ConversationAttachmentKind::Pdf => "PDF",
    }
}

/// Returns the browser file picker accept list for one attachment kind.
/// 返回单种附件类型对应的浏览器文件选择 accept 列表。
fn composer_attachment_kind_accept(kind: &ConversationAttachmentKind) -> &'static str {
    match kind {
        ConversationAttachmentKind::Image => "image/png,image/jpeg,image/webp,image/gif,image/bmp",
        ConversationAttachmentKind::Audio => {
            "audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/flac,audio/ogg"
        }
        ConversationAttachmentKind::Video => {
            "video/mp4,video/quicktime,video/x-matroska,video/webm,video/x-msvideo"
        }
        ConversationAttachmentKind::Pdf => "application/pdf",
    }
}

/// Returns the current in-memory transcript projection for one session from a concrete workspace snapshot.
/// 从具体工作区快照返回单个会话当前的内存转录投影。
fn in_memory_session_messages_from_workspace(
    workspace_snapshot: &WorkspaceSnapshot,
    session_id: SessionId,
) -> Option<Vec<SessionMessageEntry>> {
    if let Some(runtime_state) = workspace_snapshot.session_runtime_state.get(&session_id) {
        let messages = conversation_state_to_session_messages(&runtime_state.conversation_state);
        if !messages.is_empty() {
            return Some(filter_legacy_goal_internal_user_messages(messages));
        }
    }
    workspace_snapshot
        .session_messages
        .get(&session_id)
        .cloned()
        .map(filter_legacy_goal_internal_user_messages)
}

/// Removes legacy persisted Goal internal prompts that were incorrectly stored as user messages.
/// 移除历史上被错误持久化成用户消息的 Goal 内部提示词。
fn filter_legacy_goal_internal_user_messages(
    messages: Vec<SessionMessageEntry>,
) -> Vec<SessionMessageEntry> {
    messages
        .into_iter()
        .filter(|message| !session_message_is_legacy_goal_internal_user_prompt(message))
        .collect()
}

/// Rewrites one runtime state after removing legacy Goal internal user messages.
/// 移除历史 Goal 内部用户消息后重写单个运行态。
fn sanitize_runtime_state_legacy_goal_internal_messages(
    runtime_state: &mut SessionRuntimeStateEntry,
) {
    let messages = conversation_state_to_session_messages(&runtime_state.conversation_state);
    if messages
        .iter()
        .any(session_message_is_legacy_goal_internal_user_prompt)
    {
        runtime_state.conversation_state = conversation_state_from_session_messages(
            &filter_legacy_goal_internal_user_messages(messages),
        );
    }
}

/// Returns whether one message is a known legacy Goal internal prompt persisted before the hidden fix.
/// 返回单条消息是否为隐藏修复前已知被持久化的历史 Goal 内部提示词。
fn session_message_is_legacy_goal_internal_user_prompt(message: &SessionMessageEntry) -> bool {
    if message.kind != SessionMessageKind::User {
        return false;
    }
    let body = message.body.trim_start();
    body.starts_with("Continue working toward the active thread goal.")
        || body.starts_with("The active thread goal has reached its token budget.")
        || body.starts_with("The active thread goal objective was edited by the user.")
}

/// Submits one user prompt through the shared agent runtime and returns the immediate workbench snapshot.
/// 通过共享 Agent 运行时提交一条用户提示词，并返回即时工作台快照。
async fn service_submit_conversation_prompt(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    project_id: Option<String>,
    conversation_id: Option<String>,
    prompt: String,
    hidden_model_guidance: Option<String>,
    execution_mode: Option<String>,
    reasoning_effort: Option<String>,
    attachments: Option<Vec<ComposerAttachmentSummary>>,
    disabled_ai_capability_kinds: Option<Vec<String>>,
    disabled_ai_capability_target_selectors: Option<Vec<String>>,
    ai_capability_target_order_overrides: Option<BTreeMap<String, Vec<String>>>,
) -> Result<WorkbenchSnapshot, String> {
    let prompt = prompt.trim().to_string();
    webui_trace(
        "submit_prompt_received",
        format!(
            "conversation_id={} project_id={} prompt_chars={} attachments={}",
            conversation_id.as_deref().unwrap_or("<draft>"),
            project_id.as_deref().unwrap_or("<none>"),
            prompt.chars().count(),
            attachments.as_ref().map(Vec::len).unwrap_or(0)
        ),
    );
    let attachments = attachments
        .unwrap_or_default()
        .into_iter()
        .map(composer_attachment_summary_to_core)
        .collect::<Result<Vec<_>, _>>()?;
    if prompt.is_empty() && attachments.is_empty() {
        return Err(String::from("请输入任务指令。"));
    }

    // Measures runtime handle acquisition before workspace hydration begins.
    // 衡量工作区水合开始前获取运行时句柄的耗时。
    let runtime_parts_started_at = current_unix_millis_value();
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    webui_trace(
        "submit_prompt_runtime_parts_ready",
        format!(
            "conversation_id={} elapsed_ms={}",
            conversation_id.as_deref().unwrap_or("<draft>"),
            current_unix_millis_value().saturating_sub(runtime_parts_started_at)
        ),
    );
    let submission_session_id = conversation_id.as_deref().and_then(parse_session_id);
    // Measures retained workspace reuse without cloning the full workbench snapshot on the hot path.
    // 衡量保留工作区复用，并避免在热路径克隆完整工作台快照。
    let retained_snapshot_started_at = current_unix_millis_value();
    let (preserved_workspace_run_state, retained_context_available, retained_workspace_snapshot) = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let active_kernel_sessions = active_kernel_session_ids(&guard);
        let retained_context_available = submission_session_id.is_some_and(|session_id| {
            guard
                .workspace_snapshot
                .as_ref()
                .is_some_and(|workspace_snapshot| {
                    retained_submission_snapshot_has_session_context(workspace_snapshot, session_id)
                })
        });
        // Reuses the retained workspace on the submit hot path before falling back to full disk reload.
        // 在发送热路径优先复用保留工作区，再按需回退到完整磁盘重载。
        let retained_workspace_snapshot =
            guard
                .workspace_snapshot
                .as_ref()
                .and_then(|workspace_snapshot| {
                    retained_submission_snapshot_is_usable(
                        workspace_snapshot,
                        project_id.as_deref(),
                        submission_session_id,
                    )
                    .then(|| workspace_snapshot.clone())
                });
        let preserved_workspace_run_state = capture_preserved_workspace_run_state(
            guard.workspace_snapshot.as_ref(),
            &active_kernel_sessions,
            submission_session_id,
        );
        (
            preserved_workspace_run_state,
            retained_context_available,
            retained_workspace_snapshot,
        )
    };
    webui_trace_if_slow(
        "submit_prompt_retained_snapshot_slow",
        retained_snapshot_started_at,
        format!(
            "conversation_id={} retained_context_available={retained_context_available} preserved_sessions={}",
            conversation_id.as_deref().unwrap_or("<draft>"),
            preserved_workspace_run_state
                .as_ref()
                .map(|state| state.sessions.len())
                .unwrap_or_default()
        ),
    );
    let workspace_load_started_at = current_unix_millis_value();
    let (mut workspace_snapshot, workspace_source) = if let Some(workspace_snapshot) =
        retained_workspace_snapshot
    {
        (workspace_snapshot, "retained")
    } else {
        (
            load_workspace_for_submission(controller_runtime.clone(), conversation_id.as_deref())
                .await?,
            "disk",
        )
    };
    if workspace_source == "retained"
        && let Some(session_id) = submission_session_id
    {
        hydrate_retained_submission_session_if_needed(
            controller_runtime.clone(),
            &mut workspace_snapshot,
            session_id,
        )
        .await?;
    }
    webui_trace(
        "submit_prompt_workspace_ready",
        format!(
            "conversation_id={} retained_context_available={retained_context_available} source={workspace_source} elapsed_ms={}",
            conversation_id.as_deref().unwrap_or("<draft>"),
            current_unix_millis_value().saturating_sub(workspace_load_started_at)
        ),
    );
    preserve_active_session_run_state(
        preserved_workspace_run_state.as_ref(),
        &mut workspace_snapshot,
    );
    if let Some(session_id) = conversation_id.as_deref().and_then(parse_session_id) {
        let blocking_check_started_at = current_unix_millis_value();
        // Measures the active stream and kernel state lookup portion of the blocking gate.
        // 衡量阻塞闸门中活跃流与内核状态查询部分的耗时。
        let active_state_started_at = current_unix_millis_value();
        let (has_active_stream_task, has_active_kernel_turn, has_active_session_run) = {
            let guard = state
                .lock()
                .map_err(|error| format!("failed to lock service state: {error}"))?;
            (
                guard.active_stream_tasks.contains_key(&session_id),
                webui_session_kernel_has_active_turn(&guard, session_id),
                webui_session_has_active_run(&guard, session_id),
            )
        };
        webui_trace_if_slow(
            "submit_prompt_active_state_check_slow",
            active_state_started_at,
            format!("session={session_id}"),
        );
        let has_running_subagents = false;
        webui_trace(
            "submit_prompt_subagent_running_check_skipped",
            format!("session={session_id} reason=independent_subagent_lane"),
        );
        webui_trace(
            "submit_prompt_blocking_check",
            format!(
                "session={session_id} has_active_stream_task={has_active_stream_task} has_active_kernel_turn={has_active_kernel_turn} has_active_session_run={has_active_session_run} has_running_subagents={has_running_subagents} elapsed_ms={}",
                current_unix_millis_value().saturating_sub(blocking_check_started_at)
            ),
        );
        if session_has_blocking_system_prompt_work(
            &workspace_snapshot,
            &agent_runtime.provider_configuration,
            session_id,
            has_active_session_run,
            has_running_subagents,
        ) {
            webui_trace(
                "submit_prompt_queued",
                format!(
                    "session={session_id} has_active_stream_task={has_active_stream_task} has_active_kernel_turn={has_active_kernel_turn} has_running_subagents={has_running_subagents}"
                ),
            );
            let workspace_path = workspace_path_for_session(&workspace_snapshot, session_id);
            let session_ai_tool_configuration = session_ai_tool_configuration_or_default(
                &workspace_snapshot,
                session_id,
                &agent_runtime.ai_tool_configuration,
            );
            let entry = build_webui_pending_prompt_panel_entry(
                prompt,
                hidden_model_guidance.clone(),
                attachments,
                current_pending_prompt_model_reference(&agent_runtime.provider_configuration),
                pending_prompt_runtime_options_from_submission(
                    &agent_runtime.provider_configuration,
                    session_ai_tool_configuration,
                    reasoning_effort.as_deref(),
                    disabled_ai_capability_kinds.as_deref(),
                )?,
            );
            enqueue_webui_pending_prompt_panel_entry(
                &mut workspace_snapshot,
                &agent_runtime,
                session_id,
                &workspace_path,
                entry,
            )?;
            let workbench = store_and_emit_workbench_snapshot(
                &app,
                &state,
                &controller_runtime,
                &luaskills_catalog,
                &token_budget_runtime,
                &mcp_catalog,
                &agent_runtime.provider_configuration,
                &agent_runtime.ai_tool_configuration,
                workspace_snapshot,
                &logs,
            )?;
            let state_for_persist = state.clone();
            let controller_runtime_for_persist = controller_runtime.clone();
            spawn_service_task(async move {
                let snapshot =
                    match current_workspace_snapshot_from_shared_state(&state_for_persist) {
                        Ok(Some(snapshot)) => snapshot,
                        Ok(None) => return,
                        Err(error) => {
                            eprintln!(
                                "[webui-service] queued submit persist snapshot failed: {error}"
                            );
                            return;
                        }
                    };
                spawn_workspace_session_persist_task(
                    state_for_persist,
                    controller_runtime_for_persist,
                    snapshot,
                    session_id,
                    Some(String::from("queued_submit")),
                );
            });
            return Ok(workbench);
        }
    }
    let materialize_started_at = current_unix_millis_value();
    let (session_id, session_title, workspace_path) = materialize_prompt_session(
        &mut workspace_snapshot,
        project_id.as_deref(),
        conversation_id.as_deref(),
        if prompt.is_empty() {
            "附件会话"
        } else {
            &prompt
        },
    )?;
    webui_trace(
        "submit_prompt_materialize_ready",
        format!(
            "session={session_id} title_chars={} workspace_path_chars={} elapsed_ms={}",
            session_title.chars().count(),
            workspace_path.chars().count(),
            current_unix_millis_value().saturating_sub(materialize_started_at)
        ),
    );
    ensure_webui_session_runtime_state(&mut workspace_snapshot, session_id, None);
    ensure_session_ai_tool_configuration(
        &mut workspace_snapshot,
        session_id,
        &agent_runtime.ai_tool_configuration,
    );
    if conversation_id.is_some() {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard.session_subagent_navigation_rounds.remove(&session_id);
        if guard
            .active_subagent_panel
            .is_some_and(|selection| selection.parent_session_id == session_id)
        {
            guard.active_subagent_panel = None;
        }
    }
    webui_trace(
        "submit_prompt_starting_run",
        format!(
            "session={session_id} title_chars={}",
            session_title.chars().count()
        ),
    );
    let submit_run_prepare_started_at = current_unix_millis_value();
    let session_ai_tool_configuration = session_ai_tool_configuration_or_default(
        &workspace_snapshot,
        session_id,
        &agent_runtime.ai_tool_configuration,
    );
    let disabled_ai_capability_kinds = effective_workbench_disabled_ai_capability_kinds(
        session_ai_tool_configuration,
        disabled_ai_capability_kinds.as_deref(),
    )?;
    let disabled_ai_capability_target_selectors =
        parse_ai_capability_target_selectors(disabled_ai_capability_target_selectors);
    let ai_capability_target_order_overrides =
        parse_ai_capability_target_order_overrides(ai_capability_target_order_overrides)?;
    let effective_execution_mode = execution_mode.unwrap_or_else(|| String::from("build"));
    if effective_execution_mode.eq_ignore_ascii_case("plan") {
        ensure_session_can_enter_plan_mode(&controller_runtime, session_id).await?;
        let updated_at = current_unix_millis_text();
        let runtime_state = workspace_snapshot
            .session_runtime_state
            .entry(session_id)
            .or_insert_with(|| SessionRuntimeStateEntry {
                updated_at: updated_at.clone(),
                ..SessionRuntimeStateEntry::default()
            });
        runtime_state.active_work_mode = Some(String::from("plan"));
        runtime_state.updated_at = updated_at;
    }
    webui_trace(
        "submit_prompt_runtime_options_ready",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(submit_run_prepare_started_at)
        ),
    );
    let context_snapshot_started_at = current_unix_millis_value();
    snapshot_webui_context_before_user_prompt(
        &controller_runtime,
        &workspace_snapshot,
        session_id,
        PendingSessionPromptSource::UserFollowup,
    )?;
    webui_trace(
        "submit_prompt_context_snapshot_ready",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(context_snapshot_started_at)
        ),
    );
    let turn_begin_started_at = current_unix_millis_value();
    let precheck_start = {
        let mut hook_runtime = agent_runtime
            .conversation_hook_runtime
            .lock()
            .map_err(|error| format!("会话 hook runtime 加锁失败：{error}"))?;
        begin_shared_prompt_turn(
            &mut workspace_snapshot,
            &mut hook_runtime,
            SharedPromptTurnBeginInput {
                session_id,
                session_title: &session_title,
                workspace_path: &workspace_path,
                prompt_entry_id: format!(
                    "webui-prompt-{session_id}-{}",
                    current_unix_millis_text()
                ),
                prompt: &prompt,
                hidden_model_guidance: hidden_model_guidance.as_deref(),
                attachments,
                append_canonical_user_message: true,
                append_visible_user_prompt_record: true,
                source: PendingSessionPromptSource::UserFollowup,
                execution_mode: effective_execution_mode,
                reasoning_effort: reasoning_effort.as_deref().and_then(parse_reasoning_effort),
                disabled_ai_capability_kinds,
                disabled_ai_capability_target_selectors,
                ai_capability_target_order_overrides,
            },
        )
    }?;
    webui_trace(
        "submit_prompt_turn_begin_ready",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(turn_begin_started_at)
        ),
    );
    {
        let kernel_turn_started_at = current_unix_millis_value();
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        start_webui_session_kernel_user_turn(
            &mut guard,
            session_id,
            precheck_start.precheck_request.turn_id(),
        )?;
        webui_trace(
            "submit_prompt_kernel_turn_started",
            format!(
                "session={session_id} elapsed_ms={}",
                current_unix_millis_value().saturating_sub(kernel_turn_started_at)
            ),
        );
    }
    mark_webui_prompt_snapshot_preparing(&mut workspace_snapshot, session_id);
    let begin_emit_started_at = current_unix_millis_value();
    let _ = store_and_emit_workbench_snapshot_preserving_subagent_navigation(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot.clone(),
        &logs,
    )?;
    webui_trace(
        "submit_prompt_begin_workbench_emitted",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(begin_emit_started_at)
        ),
    );
    let outer_steps_started_at = current_unix_millis_value();
    apply_webui_prompt_begin_outer_steps(
        &controller_runtime,
        &mut workspace_snapshot,
        session_id,
        &session_title,
    );
    webui_trace(
        "submit_prompt_outer_steps_ready",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(outer_steps_started_at)
        ),
    );
    let hook_snapshot_started_at = current_unix_millis_value();
    agent_runtime
        .vmm_hook_runtime
        .replace_snapshot(build_vmm_hook_config_snapshot(
            &agent_runtime.provider_configuration,
            &workspace_snapshot,
        ));
    webui_trace(
        "submit_prompt_hook_snapshot_ready",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(hook_snapshot_started_at)
        ),
    );
    let precheck_plan_started_at = current_unix_millis_value();
    let precheck_plan = webui_shared_prompt_precheck_plan(
        &agent_runtime,
        &workspace_snapshot,
        session_id,
        &workspace_path,
    )?;
    webui_trace(
        "submit_prompt_precheck_plan_ready",
        format!(
            "session={session_id} has_hooks={} skip={} labels={} elapsed_ms={}",
            precheck_plan.has_precheck_hooks,
            precheck_plan.should_skip_precheck,
            precheck_plan.progress_labels.len(),
            current_unix_millis_value().saturating_sub(precheck_plan_started_at)
        ),
    );
    let store_emit_started_at = current_unix_millis_value();
    let mut workbench = store_and_emit_workbench_snapshot_preserving_subagent_navigation(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;
    webui_trace(
        "submit_prompt_workbench_emitted",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(store_emit_started_at)
        ),
    );
    let state_for_persist = state.clone();
    let controller_runtime_for_persist = controller_runtime.clone();
    spawn_service_task(async move {
        let snapshot = match current_workspace_snapshot_from_shared_state(&state_for_persist) {
            Ok(Some(snapshot)) => snapshot,
            Ok(None) => return,
            Err(error) => {
                eprintln!("[webui-service] submit begin persist snapshot failed: {error}");
                return;
            }
        };
        spawn_workspace_session_persist_task(
            state_for_persist,
            controller_runtime_for_persist,
            snapshot,
            session_id,
            Some(String::from("submit_begin")),
        );
    });
    let service_state = state.clone();
    let precheck_dispatch_started_at = current_unix_millis_value();
    if start_webui_precheck_or_continue(
        &app,
        &service_state,
        &controller_runtime,
        &agent_runtime,
        precheck_start,
        precheck_plan,
    )? {
        workbench = current_workbench_snapshot_from_state(&state)?;
    }
    webui_trace(
        "submit_prompt_precheck_dispatch_returned",
        format!(
            "session={session_id} elapsed_ms={}",
            current_unix_millis_value().saturating_sub(precheck_dispatch_started_at)
        ),
    );
    Ok(workbench)
}

/// Starts prompt-based compaction for the selected WebUI conversation.
/// 为当前选中的 WebUI 会话启动提示词式上下文压缩。
async fn service_compact_selected_conversation_context(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let selected_session_id = selected_session_id_from_state(&state)?;
    webui_trace(
        "context_compaction_requested",
        format!("session={selected_session_id}"),
    );

    let (has_active_stream_task, has_active_kernel_turn, has_active_session_run) = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        (
            guard.active_stream_tasks.contains_key(&selected_session_id),
            webui_session_kernel_has_active_turn(&guard, selected_session_id),
            webui_session_has_active_run(&guard, selected_session_id),
        )
    };
    if has_active_stream_task || has_active_kernel_turn || has_active_session_run {
        return Err(String::from(
            "当前会话仍有运行中的执行链路，暂时无法执行手动上下文压缩。",
        ));
    }

    let mut workspace_snapshot =
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    ensure_webui_session_runtime_state(&mut workspace_snapshot, selected_session_id, None);
    let runtime_state_snapshot = workspace_snapshot
        .session_runtime_state
        .get(&selected_session_id)
        .cloned()
        .unwrap_or_default();
    let full_session_messages =
        conversation_state_to_session_messages(&runtime_state_snapshot.conversation_state);
    let context_messages = if full_session_messages.is_empty() {
        in_memory_session_messages_from_workspace(&workspace_snapshot, selected_session_id)
            .unwrap_or_default()
    } else {
        full_session_messages.clone()
    };
    if context_messages.is_empty() {
        return Err(String::from("当前会话暂时没有可压缩的历史上下文。"));
    }
    let Some(plan) = plan_context_compaction(CompactionPlanInput {
        session_label: &selected_session_id.to_string(),
        messages: &context_messages,
        all_messages: &full_session_messages,
        context_start_message_id: runtime_state_snapshot.context_start_message_id.as_deref(),
        policy: Default::default(),
    }) else {
        return Err(String::from("当前会话暂时没有可压缩的历史上下文。"));
    };

    let budget_note = context_compaction_budget_note_from_state(&state, selected_session_id);
    let previous_phase = workspace_snapshot
        .session_run_phases
        .get(&selected_session_id)
        .copied()
        .unwrap_or(SessionRunPhase::Ready);
    let status_message_id = append_webui_context_compaction_status_message_to_workspace(
        &mut workspace_snapshot,
        selected_session_id,
        &budget_note,
    );
    workspace_snapshot
        .session_run_phases
        .insert(selected_session_id, SessionRunPhase::Preparing);
    if let Some(session) = workspace_snapshot
        .sessions
        .iter_mut()
        .find(|session| session.id == selected_session_id)
    {
        session.status = SessionState::Running;
        session.last_updated_label = String::from("刚刚");
        session.updated_at = current_unix_millis_text();
    }
    let turn_id = format!("context-compaction-{}", current_unix_millis_text());
    {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        start_webui_session_kernel_turn(
            &mut guard,
            selected_session_id,
            &turn_id,
            ActiveTurnKind::ContextCompaction,
        )?;
    }
    let workbench = store_and_emit_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;

    spawn_webui_context_compaction_task(
        app.clone(),
        state.clone(),
        controller_runtime.clone(),
        agent_runtime,
        selected_session_id,
        previous_phase,
        status_message_id,
        budget_note,
        plan,
    )?;
    Ok(workbench)
}

/// Stops the selected WebUI conversation run and clears guided internal queue work.
/// 停止当前选中的 WebUI 会话运行，并清理已引导的内部队列任务。
async fn service_stop_conversation_run(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let selected_session_id = selected_session_id_from_state(&state)?;
    webui_trace(
        "stop_conversation_requested",
        format!("session={selected_session_id}"),
    );
    let active_task = state
        .lock()
        .map_err(|error| format!("failed to lock service state: {error}"))?
        .active_stream_tasks
        .remove(&selected_session_id);
    let had_active_kernel_turn = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        stop_webui_session_kernel_generation(&mut guard, selected_session_id)
    };
    let had_active_stream_task = active_task.is_some();
    if let Some(active_task) = active_task {
        active_task.abort();
    }
    let mut workspace_snapshot = with_workspace_mutation(&app, &state, |workspace| {
        mark_webui_session_stop_requested_in_workspace(workspace, selected_session_id);
    })?;
    let running_subagent_task_states = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        running_webui_subagent_task_states_for_tree_from_cache(
            &mut guard,
            &workspace_snapshot,
            selected_session_id,
        )
    };
    webui_trace(
        "stop_conversation_state",
        format!(
            "session={selected_session_id} had_active_kernel_turn={had_active_kernel_turn} had_active_stream_task={had_active_stream_task} running_subagents={}",
            running_subagent_task_states.len()
        ),
    );
    for (direct_parent_session_id, task_state) in &running_subagent_task_states {
        let _ = agent_runtime
            .task_runtime
            .stop_task_tree(task_state.task_id);
        mark_webui_subagent_task_stopped_in_workspace(
            &mut workspace_snapshot,
            *direct_parent_session_id,
            task_state.task_id,
            Some(task_state),
        );
    }
    if !running_subagent_task_states.is_empty() {
        let running_subagent_task_ids = running_subagent_task_states
            .iter()
            .map(|(direct_parent_session_id, state)| (*direct_parent_session_id, state.task_id))
            .collect::<Vec<_>>();
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        mark_webui_subagent_tasks_stopped_in_state(&mut guard, &running_subagent_task_ids);
    }
    let did_stop_work = stop_webui_session_work(
        &mut workspace_snapshot,
        selected_session_id,
        had_active_kernel_turn,
        !running_subagent_task_states.is_empty(),
    )?;
    if did_stop_work
        && !workspace_snapshot
            .session_runtime_state
            .contains_key(&selected_session_id)
    {
        return Err(String::from("停止后未找到会话运行时状态。"));
    }
    if did_stop_work
        && let Some(goal) = VulcanGoalStore::new(controller_runtime.clone())
            .pause_active_thread_goal(selected_session_id)
            .await?
    {
        cache_session_goal_summary(&state, selected_session_id, Some(goal))?;
    }
    let workbench = store_and_emit_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;
    if did_stop_work {
        let state_for_persist = state.clone();
        let controller_runtime_for_persist = controller_runtime.clone();
        spawn_service_task(async move {
            let snapshot = match current_workspace_snapshot_from_shared_state(&state_for_persist) {
                Ok(Some(snapshot)) => snapshot,
                Ok(None) => return,
                Err(error) => {
                    eprintln!(
                        "[webui-service] stopped conversation persist snapshot failed: {error}"
                    );
                    return;
                }
            };
            if !snapshot
                .session_runtime_state
                .contains_key(&selected_session_id)
            {
                return;
            }
            if let Err(error) = persist_workspace_session_update(
                Some(&state_for_persist),
                controller_runtime_for_persist,
                &snapshot,
                selected_session_id,
            )
            .await
            {
                eprintln!(
                    "[webui-service] stopped conversation background persist failed: {error}"
                );
            }
        });
    }
    Ok(workbench)
}

/// Stops one live command session and rebuilds the WebUI workbench snapshot.
/// 停止单条实时命令会话并重建 WebUI 工作台快照。
async fn service_stop_command_session(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    command_session_id: String,
    owner_session_id: Option<String>,
) -> Result<WorkbenchSnapshot, String> {
    let (controller_runtime, agent_runtime, _, _, _, _) = runtime_parts_from_state(&state)?;
    let command_session_id = command_session_id
        .parse::<SessionId>()
        .map_err(|error| format!("invalid command session id '{command_session_id}': {error}"))?;
    let owner_session_id = match owner_session_id {
        Some(owner_session_id) => owner_session_id
            .parse::<SessionId>()
            .map_err(|error| format!("invalid owner session id '{owner_session_id}': {error}"))?,
        None => agent_runtime
            .command_session_runtime
            .try_snapshot_session_by_id(command_session_id)
            .map(|snapshot| snapshot.owner_session_id)
            .ok_or_else(|| {
                format!("Command session `{command_session_id}` was not found in the live runtime.")
            })?,
    };
    webui_trace(
        "stop_command_session_requested",
        format!("owner={owner_session_id} command_session={command_session_id}"),
    );
    agent_runtime
        .command_session_runtime
        .stop_session(owner_session_id, command_session_id, Some(1500))
        .await?;
    let workspace_snapshot =
        current_workspace_snapshot_from_shared_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    store_current_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &agent_runtime,
        workspace_snapshot,
    )
}

/// Saves or updates the selected session goal through the user-facing WebUI API.
/// 通过面向用户的 WebUI API 保存或更新当前会话目标。
///
/// # Parameters
/// 参数
/// `app` emits the refreshed workbench snapshot.
/// `app` 发出刷新后的工作台快照。
/// `state` owns the retained service bridge state.
/// `state` 持有保留的服务桥接状态。
/// `request` carries the target conversation and objective.
/// `request` 携带目标会话与目标文本。
///
/// # Returns
/// 返回值
/// The refreshed workbench snapshot after the goal is persisted.
/// 目标持久化后的刷新工作台快照。
async fn service_save_session_goal(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: SessionGoalSaveRequest,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let session_id = session_goal_request_session_id(&state, request.conversation_id.as_deref())?;
    validate_session_goal_objective(&request.objective)?;
    validate_session_goal_budget(request.token_budget)?;
    ensure_regular_session_exists(&state, session_id, "保存目标")?;
    ensure_session_not_in_plan_mode_for_goal(&state, session_id)?;
    let objective = request.objective.trim().to_string();
    let goal_store = VulcanGoalStore::new(controller_runtime.clone());
    let existing_goal = goal_store
        .get_thread_goal(session_id)
        .await
        .map_err(|error| format!("读取当前目标失败：{error}"))?;
    let objective_changed = existing_goal
        .as_ref()
        .is_some_and(|goal| goal.objective != objective);
    let goal = if let Some(existing_goal) = existing_goal {
        if existing_goal.status == ThreadGoalStatus::Complete {
            goal_store
                .replace_thread_goal(
                    session_id,
                    objective.as_str(),
                    ThreadGoalStatus::Active,
                    request.token_budget,
                )
                .await
                .map_err(|error| format!("保存目标失败：{error}"))?
        } else {
            goal_store
                .update_thread_goal(
                    session_id,
                    GoalUpdate {
                        objective: Some(objective),
                        status: Some(saved_goal_status_after_edit(existing_goal.status)),
                        token_budget: Some(request.token_budget),
                        expected_goal_id: Some(existing_goal.goal_id),
                    },
                )
                .await
                .map_err(|error| format!("保存目标失败：{error}"))?
                .ok_or_else(|| String::from("当前目标已变化，请刷新后重试。"))?
        }
    } else {
        goal_store
            .replace_thread_goal(
                session_id,
                objective.as_str(),
                ThreadGoalStatus::Active,
                request.token_budget,
            )
            .await
            .map_err(|error| format!("保存目标失败：{error}"))?
    };
    if objective_changed
        && goal.status == ThreadGoalStatus::Active
        && let Err(error) = enqueue_session_goal_objective_updated_guidance(
            &state,
            session_id,
            &session_goal_summary_from_thread_goal(&goal),
        )
    {
        eprintln!("[webui-service] enqueue goal objective update guidance failed: {error}");
    }
    refresh_session_goal_summary_and_emit(
        app,
        state,
        &controller_runtime,
        &agent_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &logs,
        session_id,
        Some(goal),
    )
}

/// Returns the lifecycle status to keep after a user edits an existing goal.
/// 返回用户编辑既有目标后应保留的生命周期状态。
fn saved_goal_status_after_edit(status: ThreadGoalStatus) -> ThreadGoalStatus {
    if status == ThreadGoalStatus::Complete {
        ThreadGoalStatus::Active
    } else {
        status
    }
}

/// Resumes a stopped session goal as a fresh user-approved budget stage.
/// 将已停止的会话目标恢复为用户确认后的新预算阶段。
///
/// # Parameters
/// 参数
/// `app` emits the refreshed workbench snapshot.
/// `app` 发出刷新后的工作台快照。
/// `state` owns the retained service bridge state.
/// `state` 持有保留的服务桥接状态。
/// `request` carries the target session, objective, and next-stage budget.
/// `request` 携带目标会话、目标文本与下一阶段预算。
///
/// # Returns
/// 返回值
/// The refreshed workbench snapshot after the goal resumes.
/// 目标恢复后的刷新工作台快照。
async fn service_resume_session_goal(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: SessionGoalResumeRequest,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let session_id = session_goal_request_session_id(&state, request.conversation_id.as_deref())?;
    validate_session_goal_objective(&request.objective)?;
    validate_session_goal_budget(request.token_budget)?;
    ensure_regular_session_exists(&state, session_id, "继续目标")?;
    ensure_session_not_in_plan_mode_for_goal(&state, session_id)?;
    let objective = request.objective.trim().to_string();
    let goal_store = VulcanGoalStore::new(controller_runtime.clone());
    let existing_goal = goal_store
        .get_thread_goal(session_id)
        .await
        .map_err(|error| format!("读取当前目标失败：{error}"))?
        .ok_or_else(|| String::from("当前会话还没有可继续的目标。"))?;
    if existing_goal.status == ThreadGoalStatus::Complete {
        return Err(String::from("已完成目标不能继续，请创建新目标。"));
    }
    if existing_goal.status == ThreadGoalStatus::Active {
        return Err(String::from("当前目标已经在进行中。"));
    }
    let objective_changed = existing_goal.objective != objective;
    let goal = goal_store
        .resume_thread_goal(
            session_id,
            GoalUpdate {
                objective: Some(objective),
                status: Some(ThreadGoalStatus::Active),
                token_budget: Some(request.token_budget),
                expected_goal_id: Some(existing_goal.goal_id),
            },
        )
        .await
        .map_err(|error| format!("继续目标失败：{error}"))?
        .ok_or_else(|| String::from("当前目标已变化，请刷新后重试。"))?;
    if goal.status != ThreadGoalStatus::Active {
        return Err(String::from("当前目标状态不支持继续。"));
    }
    clear_budget_limit_reported_goal_id(&state, &goal.goal_id)?;
    if objective_changed
        && let Err(error) = enqueue_session_goal_objective_updated_guidance(
            &state,
            session_id,
            &session_goal_summary_from_thread_goal(&goal),
        )
    {
        eprintln!("[webui-service] enqueue resumed goal objective update guidance failed: {error}");
    }
    let snapshot = refresh_session_goal_summary_and_emit(
        app.clone(),
        state.clone(),
        &controller_runtime,
        &agent_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &logs,
        session_id,
        Some(goal),
    )?;
    if let Err(error) = maybe_start_session_goal_continuation_if_idle(
        &app,
        &state,
        &controller_runtime,
        &agent_runtime,
        session_id,
    )
    .await
    {
        eprintln!("[webui-service] resumed goal continuation failed: {error}");
    }
    Ok(snapshot)
}

/// Clears the selected session goal through the user-facing WebUI API.
/// 通过面向用户的 WebUI API 清理当前会话目标。
///
/// # Parameters
/// 参数
/// `app` emits the refreshed workbench snapshot.
/// `app` 发出刷新后的工作台快照。
/// `state` owns the retained service bridge state.
/// `state` 持有保留的服务桥接状态。
/// `request` carries the target conversation id.
/// `request` 携带目标会话标识。
///
/// # Returns
