/// Opens one subagent transcript surface under the selected parent conversation.
/// 打开当前父会话下的单个子代理转录界面。
async fn service_open_subagent_panel(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    parent_conversation_id: String,
    task_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let _ = runtime_parts_from_state(&state)?;
    let parent_session_id = parent_conversation_id
        .parse::<SessionId>()
        .map_err(|error| {
            format!("invalid parent conversation id '{parent_conversation_id}': {error}")
        })?;
    let task_session_id = task_id
        .parse::<SessionId>()
        .map_err(|error| format!("invalid subagent task id '{task_id}': {error}"))?;
    webui_trace(
        "open_subagent_panel_requested",
        format!("parent={parent_session_id} task={task_session_id}"),
    );
    {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        if guard.active_subagent_panel
            == Some(SelectedSubagentTaskPanel {
                parent_session_id,
                task_id: task_session_id,
            })
        {
            webui_trace(
                "open_subagent_panel_noop_active",
                format!("parent={parent_session_id} task={task_session_id}"),
            );
            return Ok(guard.workbench.clone());
        }
    }
    let cache_open_started_at = current_unix_millis_value();
    let fast_path_workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let mut workspace_snapshot = guard.workspace_snapshot.take().ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
        restore_webui_subagent_surface_detail_cache_for_task(
            &mut guard,
            &mut workspace_snapshot,
            parent_session_id,
            task_session_id,
        );
        let opened_from_cache = match open_webui_subagent_panel_from_cached_state(
            &mut guard,
            &workspace_snapshot,
            parent_session_id,
            task_session_id,
        ) {
            Ok(opened_from_cache) => opened_from_cache,
            Err(error) => {
                guard.workspace_snapshot = Some(workspace_snapshot);
                return Err(error);
            }
        };
        let workbench = opened_from_cache.then(|| {
            build_subagent_display_route_workbench_snapshot_locked(&mut guard, &workspace_snapshot)
        });
        guard.workspace_snapshot = Some(workspace_snapshot);
        workbench
    };
    webui_trace_if_slow(
        "open_subagent_panel_cache_slow",
        cache_open_started_at,
        format!(
            "parent={parent_session_id} task={task_session_id} opened_from_cache={}",
            fast_path_workbench.is_some()
        ),
    );
    if let Some(workbench) = fast_path_workbench {
        let emit_started_at = current_unix_millis_value();
        emit_workbench_event(&app, &workbench);
        webui_trace_if_slow(
            "open_subagent_panel_emit_slow",
            emit_started_at,
            format!("parent={parent_session_id} task={task_session_id} source=cache"),
        );
        return Ok(workbench);
    }
    let mut workspace_snapshot =
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    let detail_load_started_at = current_unix_millis_value();
    let detailed_state = segmented_webui_subagent_task_panel_state_for_task(
        &workspace_snapshot,
        parent_session_id,
        task_session_id,
    );
    webui_trace_if_slow(
        "open_subagent_panel_detail_load_slow",
        detail_load_started_at,
        format!(
            "parent={parent_session_id} task={task_session_id} found={}",
            detailed_state.is_some()
        ),
    );
    {
        let cache_merge_started_at = current_unix_millis_value();
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        if let Some(detailed_state) = detailed_state {
            cache_webui_subagent_surface_detail_for_task(
                &mut guard,
                &mut workspace_snapshot,
                parent_session_id,
                detailed_state.clone(),
            );
            merge_webui_subagent_task_cache_for_session(
                &mut guard,
                parent_session_id,
                vec![detailed_state],
            );
        }
        if !open_webui_subagent_panel_from_cached_state(
            &mut guard,
            &workspace_snapshot,
            parent_session_id,
            task_session_id,
        )? {
            webui_trace(
                "open_subagent_panel_missing",
                format!("parent={parent_session_id} task={task_session_id}"),
            );
            return Err(String::from("没有找到可打开的子代理任务。"));
        }
        webui_trace_if_slow(
            "open_subagent_panel_cache_merge_slow",
            cache_merge_started_at,
            format!("parent={parent_session_id} task={task_session_id}"),
        );
    }
    let emit_started_at = current_unix_millis_value();
    let snapshot = emit_subagent_display_route_workbench_snapshot(&app, &state, workspace_snapshot);
    webui_trace_if_slow(
        "open_subagent_panel_emit_slow",
        emit_started_at,
        format!("parent={parent_session_id} task={task_session_id} source=detail"),
    );
    snapshot
}

/// Opens a WebUI subagent panel from the in-memory task cache without touching disk.
/// 从内存任务缓存打开 WebUI 子代理面板，不触碰磁盘。
fn open_webui_subagent_panel_from_cached_state(
    guard: &mut ServiceBridgeState,
    workspace_snapshot: &WorkspaceSnapshot,
    parent_session_id: SessionId,
    task_session_id: SessionId,
) -> Result<bool, String> {
    let Some(task_state) = guard
        .session_subagent_tasks
        .get(&parent_session_id)
        .and_then(|tasks| tasks.get(&task_session_id))
        .cloned()
    else {
        return Ok(false);
    };
    let has_live_listener = guard
        .detached_subagent_task_listeners
        .contains(&task_session_id);
    let task_runtime = guard
        .agent_runtime
        .as_ref()
        .map(|runtime| &runtime.task_runtime);
    let is_live_running =
        webui_subagent_task_has_live_run(task_runtime, has_live_listener, task_session_id);
    let normalized = normalize_subagent_task_panel_state(&task_state, is_live_running, None);
    let has_recoverable_detail =
        webui_subagent_panel_has_recoverable_detail(workspace_snapshot, &normalized);
    let is_openable = subagent_task_panel_is_openable(&normalized, has_recoverable_detail);
    webui_trace(
        "open_subagent_panel_evaluated",
        format!(
            "parent={parent_session_id} task={task_session_id} run_state={} has_recoverable_detail={has_recoverable_detail} is_openable={is_openable} messages={}",
            subagent_run_state_key(normalized.run_state),
            workspace_snapshot
                .session_messages
                .get(&task_session_id)
                .map(Vec::len)
                .unwrap_or(0)
        ),
    );
    if !is_openable {
        return Ok(false);
    }
    guard
        .session_subagent_tasks
        .entry(parent_session_id)
        .or_default()
        .insert(task_session_id, normalized);
    guard.active_subagent_panel = Some(SelectedSubagentTaskPanel {
        parent_session_id,
        task_id: task_session_id,
    });
    Ok(true)
}

/// Closes the active subagent transcript surface and returns to the parent conversation.
/// 关闭活动子代理转录界面并返回父会话。
async fn service_close_subagent_panel(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
) -> Result<WorkbenchSnapshot, String> {
    let _ = runtime_parts_from_state(&state)?;
    let workspace_snapshot = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        webui_trace(
            "close_subagent_panel_requested",
            format!(
                "active_parent={} active_task={}",
                guard
                    .active_subagent_panel
                    .map(|selection| selection.parent_session_id.to_string())
                    .unwrap_or_else(|| String::from("<none>")),
                guard
                    .active_subagent_panel
                    .map(|selection| selection.task_id.to_string())
                    .unwrap_or_else(|| String::from("<none>"))
            ),
        );
        guard.active_subagent_panel = None;
        guard.workspace_snapshot.take().ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?
    };
    emit_subagent_display_route_workbench_snapshot(&app, &state, workspace_snapshot)
}

/// Stops one running subagent task through the shared task runtime.
/// 通过共享任务运行时停止单个运行中的子代理任务。
async fn service_stop_subagent_task(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    parent_conversation_id: String,
    task_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let (controller_runtime, agent_runtime, _, _, _, _) = runtime_parts_from_state(&state)?;
    let parent_session_id = parent_conversation_id
        .parse::<SessionId>()
        .map_err(|error| {
            format!("invalid parent conversation id '{parent_conversation_id}': {error}")
        })?;
    let task_session_id = task_id
        .parse::<SessionId>()
        .map_err(|error| format!("invalid subagent task id '{task_id}': {error}"))?;
    webui_trace(
        "stop_subagent_requested",
        format!("parent={parent_session_id} task={task_session_id}"),
    );
    let task_states_to_mark = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let workspace_snapshot = guard.workspace_snapshot.take().ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
        let root_state = guard
            .session_subagent_tasks
            .get(&parent_session_id)
            .and_then(|tasks| tasks.get(&task_session_id))
            .cloned();
        let mut task_states_to_mark = vec![(parent_session_id, task_session_id, root_state)];
        task_states_to_mark.extend(
            running_webui_subagent_task_states_for_tree_from_cache(
                &mut guard,
                &workspace_snapshot,
                task_session_id,
            )
            .into_iter()
            .map(|(direct_parent_session_id, task_state)| {
                (
                    direct_parent_session_id,
                    task_state.task_id,
                    Some(task_state),
                )
            }),
        );
        guard.workspace_snapshot = Some(workspace_snapshot);
        task_states_to_mark
    };
    let stopped_task_ids = agent_runtime.task_runtime.stop_task_tree(task_session_id)?;
    webui_trace(
        "stop_subagent_result",
        format!(
            "parent={parent_session_id} task={task_session_id} stopped_count={}",
            stopped_task_ids.len()
        ),
    );
    let stopped_task_id_set = stopped_task_ids.iter().copied().collect::<BTreeSet<_>>();
    let stopped_parent_session_ids = task_states_to_mark
        .iter()
        .filter(|(_, task_id, _)| stopped_task_id_set.contains(task_id))
        .map(|(direct_parent_session_id, _, _)| *direct_parent_session_id)
        .collect::<BTreeSet<_>>();
    let workspace_snapshot = if !stopped_task_id_set.is_empty() {
        with_workspace_mutation(&app, &state, |workspace| {
            for (direct_parent_session_id, task_id, task_state) in &task_states_to_mark {
                if !stopped_task_id_set.contains(task_id) {
                    continue;
                }
                mark_webui_subagent_task_stopped_in_workspace(
                    workspace,
                    *direct_parent_session_id,
                    *task_id,
                    task_state.as_ref(),
                );
            }
        })?
    } else {
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?
    };
    {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        if !stopped_task_id_set.is_empty() {
            let stopped_task_pairs = task_states_to_mark
                .iter()
                .filter(|(_, task_id, _)| stopped_task_id_set.contains(task_id))
                .map(|(direct_parent_session_id, task_id, _)| (*direct_parent_session_id, *task_id))
                .collect::<Vec<_>>();
            mark_webui_subagent_tasks_stopped_in_state(&mut guard, &stopped_task_pairs);
            for task_id in &stopped_task_id_set {
                guard.detached_subagent_task_listeners.remove(task_id);
                if guard
                    .active_subagent_panel
                    .is_some_and(|selection| selection.task_id == *task_id)
                {
                    guard.active_subagent_panel = None;
                }
            }
        } else {
            guard
                .detached_subagent_task_listeners
                .remove(&task_session_id);
        }
    }
    let workbench = store_current_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &agent_runtime,
        workspace_snapshot,
    )?;
    if !stopped_parent_session_ids.is_empty() {
        let state_for_persist = state.clone();
        let controller_runtime_for_persist = controller_runtime.clone();
        spawn_service_task(async move {
            let snapshot = match current_workspace_snapshot_from_shared_state(&state_for_persist) {
                Ok(Some(snapshot)) => snapshot,
                Ok(None) => return,
                Err(error) => {
                    eprintln!("[webui-service] stopped subagent persist snapshot failed: {error}");
                    return;
                }
            };
            for parent_session_id in stopped_parent_session_ids {
                if !snapshot
                    .sessions
                    .iter()
                    .any(|session| session.id == parent_session_id)
                {
                    continue;
                }
                if let Err(error) = persist_workspace_session_update(
                    Some(&state_for_persist),
                    controller_runtime_for_persist.clone(),
                    &snapshot,
                    parent_session_id,
                )
                .await
                {
                    eprintln!(
                        "[webui-service] stopped subagent background persist failed: {error}"
                    );
                }
            }
        });
    }
    Ok(workbench)
}

/// Inserts one visible pending prompt into the shared internal prompt queue.
/// 将单条可见待发送提示词插入共享内部提示词队列。
async fn service_insert_pending_prompt(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    entry_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let selected_session_id = selected_session_id_from_state(&state)?;
    let mut workspace_snapshot =
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    let workspace_path = workspace_path_for_session(&workspace_snapshot, selected_session_id);
    insert_webui_pending_prompt_into_internal_queue(
        &mut workspace_snapshot,
        &agent_runtime,
        selected_session_id,
        &workspace_path,
        &entry_id,
    )?;
    mark_webui_session_waiting_for_guided_prompt_dispatch(
        &mut workspace_snapshot,
        selected_session_id,
    );
    let mut workbench = store_and_emit_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;
    let snapshot_for_persist = current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
        String::from("service is still starting; workspace snapshot is not ready")
    })?;
    spawn_workspace_session_persist_task(
        state.clone(),
        controller_runtime.clone(),
        snapshot_for_persist,
        selected_session_id,
        Some(String::from("guided_insert")),
    );
    let started_next_prompt = match maybe_prepare_next_webui_pending_prompt(
        &app,
        &state,
        &controller_runtime,
        &agent_runtime,
        selected_session_id,
        true,
    )
    .await
    {
        Ok(started) => started,
        Err(error) => return Err(error),
    };
    if started_next_prompt {
        workbench = current_workbench_snapshot_from_state(&state)?;
    }
    Ok(workbench)
}

/// Restores one visible pending prompt into the WebUI composer and removes it from the queue.
/// 将单条可见待发送提示词恢复到 WebUI 输入区，并从队列中移除。
async fn service_edit_pending_prompt(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    entry_id: String,
) -> Result<PendingPromptSummary, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let selected_session_id = selected_session_id_from_state(&state)?;
    let mut workspace_snapshot =
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    let summary = {
        let Some(runtime_state) = workspace_snapshot
            .session_runtime_state
            .get_mut(&selected_session_id)
        else {
            return Err(String::from("当前会话没有可编辑的待发送队列。"));
        };
        let Some(entry) = remove_pending_prompt_panel_entry(&mut runtime_state.ui_state, &entry_id)
        else {
            return Err(String::from("没有找到待编辑的待发送提示词。"));
        };
        runtime_state.updated_at = current_unix_millis_text();
        pending_prompt_summary_from_panel_entry(&entry)
    };
    store_and_emit_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;
    let snapshot_for_persist = current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
        String::from("service is still starting; workspace snapshot is not ready")
    })?;
    spawn_workspace_session_persist_task(
        state.clone(),
        controller_runtime.clone(),
        snapshot_for_persist,
        selected_session_id,
        Some(String::from("pending_edit")),
    );
    Ok(summary)
}

/// Removes one visible pending prompt from the selected conversation queue.
/// 从当前选中会话队列中移除单条可见待发送提示词。
async fn service_remove_pending_prompt(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    entry_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let selected_session_id = selected_session_id_from_state(&state)?;
    let mut workspace_snapshot =
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    let removed = if let Some(runtime_state) = workspace_snapshot
        .session_runtime_state
        .get_mut(&selected_session_id)
    {
        if remove_pending_prompt_panel_entry(&mut runtime_state.ui_state, &entry_id).is_some() {
            runtime_state.updated_at = current_unix_millis_text();
            true
        } else {
            false
        }
    } else {
        false
    };
    let workbench = store_and_emit_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;
    if removed {
        let snapshot_for_persist =
            current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
                String::from("service is still starting; workspace snapshot is not ready")
            })?;
        spawn_workspace_session_persist_task(
            state.clone(),
            controller_runtime.clone(),
            snapshot_for_persist,
            selected_session_id,
            Some(String::from("pending_remove")),
        );
    }
    Ok(workbench)
}

/// Reorders the visible pending prompt queue for the selected conversation.
/// 重排当前选中会话的可见待发送提示词队列。
async fn service_reorder_pending_prompts(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    conversation_id: Option<String>,
    dragged_entry_id: String,
    target_entry_id: Option<String>,
) -> Result<WorkbenchSnapshot, String> {
    let (
        controller_runtime,
        agent_runtime,
        luaskills_catalog,
        token_budget_runtime,
        mcp_catalog,
        logs,
    ) = runtime_parts_from_state(&state)?;
    let selected_session_id = conversation_id
        .as_deref()
        .and_then(parse_session_id)
        .map(Ok)
        .unwrap_or_else(|| selected_session_id_from_state(&state))?;
    let mut workspace_snapshot =
        current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
            String::from("service is still starting; workspace snapshot is not ready")
        })?;
    workspace_snapshot.selected_session = selected_session_id;
    let drop_target = target_entry_id
        .filter(|entry_id| !entry_id.trim().is_empty())
        .map(PendingPromptPanelDropTarget::Before)
        .unwrap_or(PendingPromptPanelDropTarget::End);
    let did_reorder = if let Some(runtime_state) = workspace_snapshot
        .session_runtime_state
        .get_mut(&selected_session_id)
    {
        if apply_pending_prompt_panel_drop_target(
            &mut runtime_state.ui_state,
            &dragged_entry_id,
            &drop_target,
        ) {
            runtime_state.updated_at = current_unix_millis_text();
            true
        } else {
            false
        }
    } else {
        false
    };
    let workbench = store_and_emit_workbench_snapshot(
        &app,
        &state,
        &controller_runtime,
        &luaskills_catalog,
        &token_budget_runtime,
        &mcp_catalog,
        &agent_runtime.provider_configuration,
        &agent_runtime.ai_tool_configuration,
        workspace_snapshot,
        &logs,
    )?;
    if did_reorder {
        let snapshot_for_persist =
            current_workspace_snapshot_from_state(&state)?.ok_or_else(|| {
                String::from("service is still starting; workspace snapshot is not ready")
            })?;
        spawn_workspace_session_persist_task(
            state.clone(),
            controller_runtime.clone(),
            snapshot_for_persist,
            selected_session_id,
            Some(String::from("pending_reorder")),
        );
    }
    Ok(workbench)
}

/// Selects and persists the active workbench provider/model pair.
/// 选择并持久化当前工作台使用的供应商与模型组合。
async fn service_select_workbench_model(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    provider_id: String,
    model_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let provider_id = provider_id.trim().to_string();
    let model_id = model_id.trim().to_string();
    if provider_id.is_empty() || model_id.is_empty() {
        return Err(String::from("模型选择缺少 Provider 或模型标识。"));
    }

    let (
        controller_runtime,
        persist_session_id,
        persist_workspace_snapshot,
        workbench,
        default_ai_tool_configuration,
    ) = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let controller_runtime = guard.controller_runtime.clone();
        let ai_tool_configuration = guard
            .agent_runtime
            .as_ref()
            .map(|runtime| runtime.ai_tool_configuration.clone())
            .unwrap_or_default();
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        let has_model = provider_config::effective_model_choices(
            &provider_id,
            &agent_runtime.provider_configuration,
        )
        .into_iter()
        .any(|choice| choice.id == model_id);
        if !has_model {
            return Err(format!(
                "模型 `{model_id}` 不在 `{provider_id}` 的已启用模型列表中。"
            ));
        }

        let mut next_configuration = agent_runtime.provider_configuration.clone();
        next_configuration.model = Some(format!("{provider_id}/{model_id}"));
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("保存模型选择失败：{error}"))?;
        agent_runtime.provider_configuration = next_configuration.clone();
        let selected_effort = active_reasoning_selection_effort(&next_configuration);
        let openrouter_endpoint_route = (provider_id == "openrouter")
            .then(|| {
                provider_config::openrouter_endpoint_route_for_model(&next_configuration, &model_id)
            })
            .flatten();
        let persist_session_id = guard.workspace_snapshot.as_mut().and_then(|workspace| {
            selected_session_runtime_state_mut(workspace).map(|(session_id, runtime_state)| {
                runtime_state.active_provider_id = Some(provider_id.clone());
                runtime_state.active_model_id = Some(model_id.clone());
                runtime_state.active_openrouter_endpoint_route = openrouter_endpoint_route;
                if let Some(selected_effort) = selected_effort {
                    runtime_state.active_reasoning_effort = Some(selected_effort);
                }
                runtime_state.updated_at = current_unix_millis_text();
                session_id
            })
        });
        refresh_workbench_runtime_controls_locked(
            &mut guard,
            &next_configuration,
            &ai_tool_configuration,
        );
        (
            controller_runtime,
            persist_session_id,
            guard.workspace_snapshot.clone(),
            guard.workbench.clone(),
            ai_tool_configuration,
        )
    };

    if let (Some(controller_runtime), Some(session_id), Some(workspace_snapshot)) = (
        controller_runtime,
        persist_session_id,
        persist_workspace_snapshot,
    ) {
        if let Some(addon_state) = session_addon_state_from_workspace_snapshot(
            &workspace_snapshot,
            session_id,
            &default_ai_tool_configuration,
            &[SessionAddonNamespace::RuntimeControls],
        ) {
            spawn_workspace_session_addon_state_persist_task(
                app.clone(),
                state.clone(),
                controller_runtime,
                workspace_snapshot,
                session_id,
                addon_state,
                vec![SessionAddonNamespace::RuntimeControls],
                Some(String::from("model_selection")),
            );
        }
    }

    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Lists backend-managed secondary routes for one workbench provider/model pair.
/// 列出单个工作台 Provider/模型组合的后端二级路由。
async fn service_list_workbench_model_secondary_routes(
    state: SharedServiceBridgeState,
    provider_id: String,
    model_id: String,
) -> Result<Vec<ProviderModelSecondaryRouteSummary>, String> {
    let provider_id = provider_id.trim().to_string();
    let model_id = model_id.trim().to_string();
    if provider_id != "openrouter" {
        return Ok(Vec::new());
    }
    let provider_configuration = {
        let guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        guard
            .agent_runtime
            .as_ref()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?
            .provider_configuration
            .clone()
    };
    ensure_provider_model_enabled(&provider_configuration, &provider_id, &model_id)?;
    let active_route =
        provider_config::openrouter_endpoint_route_for_model(&provider_configuration, &model_id);
    let api_key = provider_configuration
        .provider
        .get("openrouter")
        .map(|entry| entry.options.resolved_api_key())
        .transpose()?
        .flatten();
    let choices = fetch_openrouter_secondary_route_choices(model_id.clone(), api_key).await?;
    Ok(choices
        .into_iter()
        .map(|choice| {
            let active = active_route
                .as_ref()
                .is_some_and(|selection| selection.tag == choice.tag);
            choice.into_summary(&provider_id, &model_id, active)
        })
        .collect())
}

/// Persists or clears one backend-managed secondary route for the active WebUI workbench model.
/// 为当前 WebUI 工作台模型持久化或清除一条后端二级路由。
async fn service_select_workbench_model_secondary_route(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: ProviderModelSecondaryRouteRequest,
) -> Result<WorkbenchSnapshot, String> {
    let provider_id = request.provider_id.trim().to_string();
    let model_id = request.model_id.trim().to_string();
    if provider_id != "openrouter" {
        return Err(String::from("当前只有 OpenRouter 支持二级供应商选择。"));
    }
    let selection = request.route.map(openrouter_route_selection_from_service);
    let (
        controller_runtime,
        persist_session_id,
        persist_workspace_snapshot,
        workbench,
        default_ai_tool_configuration,
    ) = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let controller_runtime = guard.controller_runtime.clone();
        let ai_tool_configuration = guard
            .agent_runtime
            .as_ref()
            .map(|runtime| runtime.ai_tool_configuration.clone())
            .unwrap_or_default();
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        ensure_provider_model_enabled(
            &agent_runtime.provider_configuration,
            &provider_id,
            &model_id,
        )?;
        let mut next_configuration = agent_runtime.provider_configuration.clone();
        provider_config::set_openrouter_endpoint_route_for_model(
            &mut next_configuration,
            &model_id,
            selection.clone(),
        );
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("保存 OpenRouter 二级供应商失败：{error}"))?;
        agent_runtime.provider_configuration = next_configuration.clone();
        let persist_session_id = guard.workspace_snapshot.as_mut().and_then(|workspace| {
            selected_session_runtime_state_mut(workspace).map(|(session_id, runtime_state)| {
                if runtime_state.active_provider_id.as_deref() == Some("openrouter")
                    && runtime_state.active_model_id.as_deref() == Some(model_id.as_str())
                {
                    runtime_state.active_openrouter_endpoint_route = selection.clone();
                    runtime_state.updated_at = current_unix_millis_text();
                }
                session_id
            })
        });
        refresh_workbench_runtime_controls_locked(
            &mut guard,
            &next_configuration,
            &ai_tool_configuration,
        );
        (
            controller_runtime,
            persist_session_id,
            guard.workspace_snapshot.clone(),
            guard.workbench.clone(),
            ai_tool_configuration,
        )
    };
    if let (Some(controller_runtime), Some(session_id), Some(workspace_snapshot)) = (
        controller_runtime,
        persist_session_id,
        persist_workspace_snapshot,
    ) {
        if let Some(addon_state) = session_addon_state_from_workspace_snapshot(
            &workspace_snapshot,
            session_id,
            &default_ai_tool_configuration,
            &[SessionAddonNamespace::RuntimeControls],
        ) {
            spawn_workspace_session_addon_state_persist_task(
                app.clone(),
                state.clone(),
                controller_runtime,
                workspace_snapshot,
                session_id,
                addon_state,
                vec![SessionAddonNamespace::RuntimeControls],
                Some(String::from("openrouter_endpoint_route")),
            );
        }
    }
    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Ensures one provider/model pair is currently visible in the effective model list.
/// 确认单个 Provider/模型组合当前位于有效模型列表中。
fn ensure_provider_model_enabled(
    provider_configuration: &ProviderConfigurationFile,
    provider_id: &str,
    model_id: &str,
) -> Result<(), String> {
    let has_model = provider_config::effective_model_choices(provider_id, provider_configuration)
        .into_iter()
        .any(|choice| choice.id == model_id);
    if has_model {
        Ok(())
    } else {
        Err(format!(
            "模型 `{model_id}` 不在 `{provider_id}` 的已启用模型列表中。"
        ))
    }
}

/// Converts a service secondary-route selection into the persisted OpenRouter route type.
/// 将 service 二级路由选择转换为持久化 OpenRouter 路由类型。
fn openrouter_route_selection_from_service(
    selection: ProviderModelSecondaryRouteSelection,
) -> provider_config::OpenRouterEndpointRouteSelection {
    let tag = if selection.tag.trim().is_empty() {
        selection.route_id.trim().to_string()
    } else {
        selection.tag.trim().to_string()
    };
    provider_config::OpenRouterEndpointRouteSelection {
        tag,
        provider_name: selection.provider_name.trim().to_string(),
        endpoint_name: selection.endpoint_name.trim().to_string(),
    }
}

/// Projects a persisted OpenRouter route into the service secondary-route summary.
/// 将持久化 OpenRouter 路由投影为 service 二级路由摘要。
fn provider_secondary_route_summary_from_openrouter_selection(
    provider_id: &str,
    model_id: &str,
    selection: provider_config::OpenRouterEndpointRouteSelection,
    active: bool,
) -> ProviderModelSecondaryRouteSummary {
    let label = selection.display_label();
    ProviderModelSecondaryRouteSummary {
        provider_id: provider_id.to_string(),
        model_id: model_id.to_string(),
        route_id: selection.tag.clone(),
        tag: selection.tag,
        provider_name: selection.provider_name.clone(),
        endpoint_name: selection.endpoint_name.clone(),
        subtitle: if selection.endpoint_name.trim().is_empty() {
            String::from("已选择")
        } else {
            selection.endpoint_name
        },
        label,
        active,
    }
}

/// Minimal OpenRouter endpoint catalog response used by the WebUI secondary-route service.
/// WebUI 二级路由服务使用的最小 OpenRouter 端点目录响应。
#[derive(Debug, Clone, Deserialize)]
struct OpenRouterModelEndpointsResponse {
    /// Response payload body containing endpoint rows.
    /// 包含端点行的响应载荷主体。
    data: OpenRouterModelEndpointsData,
}

/// Minimal OpenRouter endpoint catalog payload.
/// 最小 OpenRouter 端点目录载荷。
#[derive(Debug, Clone, Deserialize)]
struct OpenRouterModelEndpointsData {
    /// Endpoint rows available for the requested model.
    /// 目标模型可用的端点行。
    #[serde(default)]
    endpoints: Vec<OpenRouterModelEndpointRecord>,
}

/// Minimal OpenRouter endpoint record.
/// 最小 OpenRouter 端点记录。
#[derive(Debug, Clone, Deserialize)]
struct OpenRouterModelEndpointRecord {
    /// Stable endpoint tag forwarded to `provider.order`.
    /// 转发到 `provider.order` 的稳定端点标签。
    tag: Option<String>,
    /// Human-readable upstream provider name.
    /// 人类可读的上游供应商名称。
    provider_name: Option<String>,
    /// Human-readable endpoint name.
    /// 人类可读的端点名称。
    name: Option<String>,
    /// Optional recent latency summary.
    /// 可选近期延迟摘要。
    latency_last_30m: Option<Value>,
    /// Optional recent uptime summary.
    /// 可选近期可用性摘要。
    uptime_last_30m: Option<Value>,
    /// Optional recent throughput summary.
    /// 可选近期吞吐速度摘要。
    throughput_last_30m: Option<Value>,
    /// Optional pricing payload returned by OpenRouter.
    /// OpenRouter 返回的可选价格载荷。
    pricing: Option<OpenRouterEndpointPricingRecord>,
}

/// Minimal OpenRouter endpoint pricing payload.
/// 最小 OpenRouter 端点价格载荷。
#[derive(Debug, Clone, Deserialize)]
struct OpenRouterEndpointPricingRecord {
    /// Optional prompt price string.
    /// 可选输入价格字符串。
    prompt: Option<String>,
    /// Optional completion price string.
    /// 可选输出价格字符串。
    completion: Option<String>,
    /// Optional cache-read price string.
    /// 可选缓存读取价格字符串。
    input_cache_read: Option<String>,
}

/// Service-local OpenRouter endpoint choice before projection.
/// 投影前的 service 本地 OpenRouter 端点选项。
#[derive(Debug, Clone)]
struct OpenRouterSecondaryRouteChoice {
    /// Stable endpoint tag forwarded to OpenRouter.
    /// 转发到 OpenRouter 的稳定端点标签。
    tag: String,
    /// Human-readable upstream provider name.
    /// 人类可读的上游供应商名称。
    provider_name: String,
    /// Human-readable endpoint name.
    /// 人类可读的端点名称。
    endpoint_name: String,
    /// Optional prompt price in USD per token.
    /// 可选输入侧每 token 美元价格。
    prompt_price_per_token_usd: Option<f64>,
    /// Optional completion price in USD per token.
    /// 可选输出侧每 token 美元价格。
    completion_price_per_token_usd: Option<f64>,
    /// Optional cache-read price in USD per token.
    /// 可选缓存读取每 token 美元价格。
    cache_read_price_per_token_usd: Option<f64>,
    /// Optional latency in milliseconds.
    /// 可选延迟毫秒数。
    latency_last_30m_ms: Option<f64>,
    /// Optional uptime percentage.
    /// 可选可用性百分比。
    uptime_last_30m_percent: Option<f64>,
    /// Optional throughput in tokens per second.
    /// 可选每秒 token 吞吐速度。
    throughput_last_30m_tps: Option<f64>,
}

impl OpenRouterSecondaryRouteChoice {
    /// Converts this choice into one WebUI route summary.
    /// 将当前选项转换为 WebUI 路由摘要。
    fn into_summary(
        self,
        provider_id: &str,
        model_id: &str,
        active: bool,
    ) -> ProviderModelSecondaryRouteSummary {
        let label = if self.provider_name.trim().is_empty() {
            self.tag.clone()
        } else {
            self.provider_name.clone()
        };
        let subtitle = openrouter_secondary_route_subtitle(&self);
        ProviderModelSecondaryRouteSummary {
            provider_id: provider_id.to_string(),
            model_id: model_id.to_string(),
            route_id: self.tag.clone(),
            tag: self.tag,
            subtitle,
            provider_name: self.provider_name,
            endpoint_name: self.endpoint_name,
            label,
            active,
        }
    }
}

/// Loads the OpenRouter endpoint catalog for one exact model identifier.
/// 加载某个精确模型标识对应的 OpenRouter 端点目录。
async fn fetch_openrouter_secondary_route_choices(
    model_id: String,
    api_key: Option<String>,
) -> Result<Vec<OpenRouterSecondaryRouteChoice>, String> {
    let url = format!("https://openrouter.ai/api/v1/models/{model_id}/endpoints");
    let client = reqwest::Client::new();
    let mut request = client.get(url.clone());
    if let Some(api_key) = api_key.as_deref().filter(|value| !value.trim().is_empty()) {
        request = request.bearer_auth(api_key.trim());
    }
    let response = request
        .send()
        .await
        .map_err(|error| format!("请求 OpenRouter 二级供应商目录失败：{error}"))?;
    if !response.status().is_success() {
        return Err(format!(
            "请求 OpenRouter 二级供应商目录失败：HTTP {}",
            response.status()
        ));
    }
    let payload = response
        .json::<OpenRouterModelEndpointsResponse>()
        .await
        .map_err(|error| format!("解析 OpenRouter 二级供应商目录失败：{error}"))?;
    let mut choices = payload
        .data
        .endpoints
        .into_iter()
        .filter_map(openrouter_endpoint_record_to_secondary_route_choice)
        .collect::<Vec<_>>();
    choices.sort_by(|left, right| {
        left.provider_name
            .cmp(&right.provider_name)
            .then_with(|| left.tag.cmp(&right.tag))
    });
    choices.dedup_by(|left, right| left.tag == right.tag);
    Ok(choices)
}

/// Converts one raw OpenRouter endpoint record into a route choice.
/// 将单条原始 OpenRouter 端点记录转换为路由选项。
fn openrouter_endpoint_record_to_secondary_route_choice(
    record: OpenRouterModelEndpointRecord,
) -> Option<OpenRouterSecondaryRouteChoice> {
    let tag = record.tag?.trim().to_string();
    if tag.is_empty() {
        return None;
    }
    let provider_name = record
        .provider_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(tag.as_str())
        .to_string();
    let endpoint_name = record
        .name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(provider_name.as_str())
        .to_string();
    Some(OpenRouterSecondaryRouteChoice {
        tag,
        provider_name,
        endpoint_name,
        prompt_price_per_token_usd: record
            .pricing
            .as_ref()
            .and_then(|pricing| pricing.prompt.as_deref())
            .and_then(parse_openrouter_f64_text),
        completion_price_per_token_usd: record
            .pricing
            .as_ref()
            .and_then(|pricing| pricing.completion.as_deref())
            .and_then(parse_openrouter_f64_text),
        cache_read_price_per_token_usd: record
            .pricing
            .as_ref()
            .and_then(|pricing| pricing.input_cache_read.as_deref())
            .and_then(parse_openrouter_f64_text),
        latency_last_30m_ms: openrouter_value_as_f64(record.latency_last_30m.as_ref()),
        uptime_last_30m_percent: openrouter_value_as_f64(record.uptime_last_30m.as_ref()),
        throughput_last_30m_tps: openrouter_value_as_f64(record.throughput_last_30m.as_ref()),
    })
}

/// Builds the compact secondary line for one OpenRouter endpoint choice.
/// 为单个 OpenRouter 端点选项构建紧凑二级说明。
fn openrouter_secondary_route_subtitle(choice: &OpenRouterSecondaryRouteChoice) -> String {
    let mut parts = Vec::new();
    if let Some(prompt_price) =
        format_openrouter_price_per_mtokens(choice.prompt_price_per_token_usd)
    {
        parts.push(format!("输入 {prompt_price}"));
    }
    if let Some(completion_price) =
        format_openrouter_price_per_mtokens(choice.completion_price_per_token_usd)
    {
        parts.push(format!("输出 {completion_price}"));
    }
    if let Some(cache_read_price) =
        format_openrouter_price_per_mtokens(choice.cache_read_price_per_token_usd)
    {
        parts.push(format!("缓存 {cache_read_price}"));
    }
    if let Some(latency) = format_openrouter_latency_ms(choice.latency_last_30m_ms) {
        parts.push(format!("延迟 {latency}"));
    }
    if let Some(throughput) =
        format_openrouter_throughput_tokens_per_second(choice.throughput_last_30m_tps)
    {
        parts.push(format!("速度 {throughput}"));
    }
    if let Some(uptime) = format_openrouter_percentage(choice.uptime_last_30m_percent) {
        parts.push(format!("可用性 {uptime}"));
    }
    if parts.is_empty() {
        choice.endpoint_name.clone()
    } else {
        parts.join(" · ")
    }
}

/// Parses one OpenRouter numeric text field into a floating-point value.
/// 将单个 OpenRouter 数值文本字段解析为浮点数值。
fn parse_openrouter_f64_text(value: &str) -> Option<f64> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        None
    } else {
        trimmed.parse::<f64>().ok()
    }
}

/// Extracts one JSON numeric leaf into a floating-point value when possible.
/// 在可能的情况下，将单个 JSON 数值叶子提取为浮点数值。
fn openrouter_value_as_f64(value: Option<&Value>) -> Option<f64> {
    match value {
        Some(Value::Number(number)) => number.as_f64(),
        Some(Value::String(text)) => parse_openrouter_f64_text(text),
        Some(Value::Object(object)) => object
            .get("p50")
            .and_then(|percentile| openrouter_value_as_f64(Some(percentile))),
        _ => None,
    }
}

/// Formats one USD-per-token OpenRouter price as USD per million tokens.
/// 将 OpenRouter 每 token 美元价格格式化为每百万 token 美元价格。
fn format_openrouter_price_per_mtokens(value: Option<f64>) -> Option<String> {
    let price = value?;
    if !price.is_finite() {
        return None;
    }
    Some(format!("${:.3}/MTokens", price * 1_000_000.0))
}

/// Formats one OpenRouter latency value.
/// 格式化单个 OpenRouter 延迟值。
fn format_openrouter_latency_ms(value: Option<f64>) -> Option<String> {
    let latency = value?;
    latency.is_finite().then(|| format!("{latency:.0}ms"))
}

/// Formats one OpenRouter throughput value.
/// 格式化单个 OpenRouter 吞吐值。
fn format_openrouter_throughput_tokens_per_second(value: Option<f64>) -> Option<String> {
    let throughput = value?;
    throughput
        .is_finite()
        .then(|| format!("{throughput:.0} tok/s"))
}

/// Formats one OpenRouter percentage value.
/// 格式化单个 OpenRouter 百分比值。
fn format_openrouter_percentage(value: Option<f64>) -> Option<String> {
    let percentage = value?;
    percentage.is_finite().then(|| format!("{percentage:.1}%"))
}

/// Persists the active workbench reasoning effort through the shared provider configuration.
/// 通过共享 Provider 配置持久化当前工作台思考档位。
async fn service_select_workbench_reasoning_effort(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    effort: String,
) -> Result<WorkbenchSnapshot, String> {
    let selected_effort =
        parse_reasoning_effort(effort.trim()).ok_or_else(|| format!("未知思考档位：{effort}"))?;
    let (
        controller_runtime,
        persist_session_id,
        persist_workspace_snapshot,
        workbench,
        default_ai_tool_configuration,
    ) = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let controller_runtime = guard.controller_runtime.clone();
        let ai_tool_configuration = guard
            .agent_runtime
            .as_ref()
            .map(|runtime| runtime.ai_tool_configuration.clone())
            .unwrap_or_default();
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        let mut next_configuration = agent_runtime.provider_configuration.clone();
        next_configuration.workbench_reasoning_effort = Some(selected_effort);
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("保存思考档位失败：{error}"))?;
        agent_runtime.provider_configuration = next_configuration.clone();
        let persist_session_id = guard.workspace_snapshot.as_mut().and_then(|workspace| {
            selected_session_runtime_state_mut(workspace).map(|(session_id, runtime_state)| {
                runtime_state.active_reasoning_effort = Some(selected_effort);
                runtime_state.updated_at = current_unix_millis_text();
                session_id
            })
        });
        refresh_workbench_runtime_controls_locked(
            &mut guard,
            &next_configuration,
            &ai_tool_configuration,
        );
        (
            controller_runtime,
            persist_session_id,
            guard.workspace_snapshot.clone(),
            guard.workbench.clone(),
            ai_tool_configuration,
        )
    };

    if let (Some(controller_runtime), Some(session_id), Some(workspace_snapshot)) = (
        controller_runtime,
        persist_session_id,
        persist_workspace_snapshot,
    ) {
        if let Some(addon_state) = session_addon_state_from_workspace_snapshot(
            &workspace_snapshot,
            session_id,
            &default_ai_tool_configuration,
            &[SessionAddonNamespace::RuntimeControls],
        ) {
            spawn_workspace_session_addon_state_persist_task(
                app.clone(),
                state.clone(),
                controller_runtime,
                workspace_snapshot,
                session_id,
                addon_state,
                vec![SessionAddonNamespace::RuntimeControls],
                Some(String::from("reasoning_selection")),
            );
        }
    }

    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Saves one model provider configuration from the WebUI settings page.
/// 从 WebUI 设置页保存单个模型供应商配置。
async fn service_save_provider_configuration(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: ProviderConfigurationSaveRequest,
) -> Result<WorkbenchSnapshot, String> {
    let provider_id = request.provider_id.trim().to_ascii_lowercase();
    let definition = provider_config::supported_provider_by_id(&provider_id)
        .ok_or_else(|| format!("未找到供应商 `{provider_id}` 的目录定义。"))?;
    let mut options = PersistedProviderOptions::default();
    for field in definition.input_fields() {
        let value = request
            .fields
            .get(provider_field_request_key(field))
            .or_else(|| request.fields.get(provider_field_legacy_key(field)))
            .cloned()
            .unwrap_or_default();
        if value.trim().is_empty() {
            return Err(format!("请先填写 `{}`。", definition.field_label(field)));
        }
        options.set(field, value);
    }

    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        let mut next_configuration = agent_runtime.provider_configuration.clone();
        let is_new = !next_configuration.provider.contains_key(&provider_id);
        let entry = next_configuration
            .provider
            .entry(provider_id.clone())
            .or_insert_with(PersistedProviderEntry::default);
        entry.name = Some(definition.name.clone());
        entry.options = options;
        if is_new {
            entry.set_enabled_models(Vec::<String>::new());
        }
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("保存供应商配置失败：{error}"))?;
        agent_runtime.provider_configuration = next_configuration.clone();
        refresh_settings_projection_locked(&mut guard, &next_configuration, None);
        guard.workbench.clone()
    };
    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Removes one model provider configuration from the WebUI settings page.
/// 从 WebUI 设置页移除单个模型供应商配置。
async fn service_remove_provider_configuration(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    provider_id: String,
) -> Result<WorkbenchSnapshot, String> {
    let provider_id = provider_id.trim().to_ascii_lowercase();
    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        let mut next_configuration = agent_runtime.provider_configuration.clone();
        next_configuration.provider.remove(&provider_id);
        if next_configuration
            .model
            .as_deref()
            .and_then(provider_config::parse_active_model_reference)
            .is_some_and(|(active_provider_id, _)| active_provider_id == provider_id)
        {
            next_configuration.model = None;
        }
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("移除供应商配置失败：{error}"))?;
        agent_runtime.provider_configuration = next_configuration.clone();
        refresh_settings_projection_locked(&mut guard, &next_configuration, None);
        guard.workbench.clone()
    };
    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Saves the enabled model list for one provider from the WebUI settings page.
/// 从 WebUI 设置页保存单个供应商的启用模型列表。
async fn service_save_provider_enabled_models(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: ProviderEnabledModelsSaveRequest,
) -> Result<WorkbenchSnapshot, String> {
    let provider_id = request.provider_id.trim().to_ascii_lowercase();
    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        let mut next_configuration = agent_runtime.provider_configuration.clone();
        let catalog_ids = provider_config::catalog_model_choices(&provider_id, &next_configuration)
            .into_iter()
            .map(|model| model.id)
            .collect::<BTreeSet<_>>();
        let next_ids = request
            .enabled_model_ids
            .into_iter()
            .map(|model_id| model_id.trim().to_string())
            .filter(|model_id| !model_id.is_empty() && catalog_ids.contains(model_id))
            .collect::<Vec<_>>();
        let entry = next_configuration
            .provider
            .get_mut(&provider_id)
            .ok_or_else(|| format!("供应商 `{provider_id}` 尚未保存，无法配置模型。"))?;
        entry.set_enabled_models(next_ids);
        reconcile_active_model_after_enabled_models_change(&mut next_configuration, &provider_id);
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("保存启用模型失败：{error}"))?;
        agent_runtime.provider_configuration = next_configuration.clone();
        refresh_settings_projection_locked(&mut guard, &next_configuration, None);
        guard.workbench.clone()
    };
    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Saves one model capability override for a provider from the WebUI settings page.
/// 从 WebUI 设置页保存单个供应商模型能力覆盖。
async fn service_save_provider_model_override(
    app: ServiceEventEmitter,
    state: SharedServiceBridgeState,
    request: ProviderModelOverrideSaveRequest,
) -> Result<WorkbenchSnapshot, String> {
    let provider_id = request.provider_id.trim().to_ascii_lowercase();
    let model_id = request.model_id.trim().to_string();
    if provider_id.is_empty() || model_id.is_empty() {
        return Err(String::from("供应商与模型标识不能为空。"));
    }
    let reasoning_profile = match request.reasoning_profile_json.as_deref().map(str::trim) {
        Some("") | None => None,
        Some(raw_json) => Some(
            serde_json::from_str::<ReasoningProfileConfig>(raw_json)
                .map_err(|error| format!("推理模式附加配置 JSON 无效：{error}"))?,
        ),
    };
    let workbench = {
        let mut guard = state
            .lock()
            .map_err(|error| format!("failed to lock service state: {error}"))?;
        let agent_runtime = guard
            .agent_runtime
            .as_mut()
            .ok_or_else(|| String::from("service is still starting; agent runtime is not ready"))?;
        let mut next_configuration = agent_runtime.provider_configuration.clone();
        let catalog_ids = provider_config::catalog_model_choices(&provider_id, &next_configuration)
            .into_iter()
            .map(|model| model.id)
            .collect::<BTreeSet<_>>();
        if !catalog_ids.contains(&model_id) {
            return Err(format!("模型 `{model_id}` 不属于供应商 `{provider_id}`。"));
        }
        let entry = next_configuration
            .provider
            .get_mut(&provider_id)
            .ok_or_else(|| format!("供应商 `{provider_id}` 尚未保存，无法编辑模型能力。"))?;
        let override_entry = PersistedModelOverrideEntry {
            reasoning: request.reasoning,
            attachment: request.attachment,
            context_limit: request.context_limit,
            input_limit: request.input_limit,
            output_limit: request.output_limit,
            reasoning_profile,
            input_modalities: request
                .input_modalities
                .map(normalize_model_override_text_list)
                .filter(|items| !items.is_empty()),
            output_modalities: request
                .output_modalities
                .map(normalize_model_override_text_list)
                .filter(|items| !items.is_empty()),
        };
        if override_entry.is_empty() {
            entry.model_overrides.remove(&model_id);
        } else {
            entry.model_overrides.insert(model_id, override_entry);
        }
        provider_config::save_configuration_file(&next_configuration)
            .map_err(|error| format!("保存模型能力失败：{error}"))?;
        invalidate_runtime_prompt_tool_visibility_cache();
        agent_runtime.provider_configuration = next_configuration.clone();
        refresh_settings_projection_locked(&mut guard, &next_configuration, None);
        guard.workbench.clone()
    };
    emit_workbench_event(&app, &workbench);
    Ok(workbench)
}

/// Normalizes a user-authored string list used by model override fields.
/// 归一化模型覆盖字段使用的用户字符串列表。
fn normalize_model_override_text_list(values: Vec<String>) -> Vec<String> {
    values
        .into_iter()
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

